-- BlueCrystal schema and object DDL v1_5_13
-- Database: bluecrystal
-- Schema: whale
-- Client: Navicat or any PostgreSQL SQL client
-- Prerequisite: connect Navicat to database bluecrystal before executing this file.
-- WARNING: this file drops and recreates schema whale.

BEGIN;
DROP SCHEMA IF EXISTS whale CASCADE;
CREATE SCHEMA whale;
COMMENT ON SCHEMA whale IS 'BlueCrystal 正式业务数据 schema。';
SET search_path TO whale, public;

CREATE TABLE whale.meta_schema_version (
    schema_version TEXT PRIMARY KEY,
    CONSTRAINT chk_meta_schema_version_current CHECK (schema_version = '1.5.13')
);
COMMENT ON TABLE whale.meta_schema_version IS '【元数据】Whale schema 当前 DDL 版本。该表固定只保存当前正式 DDL 的一个版本号，不替代 Alembic 等迁移工具的迁移历史。';
COMMENT ON COLUMN whale.meta_schema_version.schema_version IS '当前 Whale schema 的语义版本号，与正式 DDL 文件版本一致。';

INSERT INTO whale.meta_schema_version(schema_version) VALUES ('1.5.13');


CREATE OR REPLACE FUNCTION whale.prevent_update_delete()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'Table % is append-only immutable snapshot table; insert a new revision instead of UPDATE/DELETE.', TG_TABLE_NAME;
END;
$$;

CREATE TABLE whale.ref_code (
    ref_code_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ref_type TEXT NOT NULL,
    code TEXT NOT NULL,
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    abbr_en TEXT,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    sort_order INTEGER NOT NULL DEFAULT 0,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(ref_type, code)
);
COMMENT ON TABLE whale.ref_code IS '【参考数据】参考代码表。保存协议类型、表角色、组织性质、资产类型、任务类型、拓扑元素类型、状态和协议枚举码等小型稳定枚举。';
COMMENT ON COLUMN whale.ref_code.ref_code_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.ref_code.ref_type IS '参考代码类型，例如 PROTOCOL、ASSET_TYPE、UNIT、DATA_TYPE；不是表名。';
COMMENT ON COLUMN whale.ref_code.code IS '参考代码值；仅 ref_code 表使用 code 表示枚举码，同一 ref_type 下唯一。';
COMMENT ON COLUMN whale.ref_code.name_zh IS '中文名称，用于中文界面、导入模板和运维查看。';
COMMENT ON COLUMN whale.ref_code.name_en IS '英文名称，用于英文界面、接口和导出文件。';
COMMENT ON COLUMN whale.ref_code.abbr_en IS '英文缩写，可为空。';
COMMENT ON COLUMN whale.ref_code.description_zh IS '中文说明，不得为空。';
COMMENT ON COLUMN whale.ref_code.description_en IS '英文说明，不得为空。';
COMMENT ON COLUMN whale.ref_code.sort_order IS '同一参考代码类型下的展示排序。';
COMMENT ON COLUMN whale.ref_code.enabled IS '是否启用该参考代码。';
COMMENT ON COLUMN whale.ref_code.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.ref_code.created_by IS '记录创建人或系统账号。';
COMMENT ON COLUMN whale.ref_code.updated_at IS '记录最后更新时间。';
COMMENT ON COLUMN whale.ref_code.updated_by IS '记录最后更新人或系统账号。';

CREATE TABLE whale.org_unit (
    org_unit_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    parent_org_unit_id BIGINT REFERENCES whale.org_unit(org_unit_id),
    org_identifier TEXT NOT NULL,
    org_nature_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(org_identifier, record_revision)
);
COMMENT ON TABLE whale.org_unit IS '【主数据】组织单元主数据。表示集团、区域公司、分公司、子公司等组织层级，是权责与绩效分解底座的组织根。';
COMMENT ON COLUMN whale.org_unit.org_unit_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.org_unit.parent_org_unit_id IS '上级组织单元，引用本表主键；为空表示顶层组织。';
COMMENT ON COLUMN whale.org_unit.org_identifier IS '组织业务稳定标识，不引用 ref_code.code。';
COMMENT ON COLUMN whale.org_unit.org_nature_ref_id IS '组织性质，取值来自 ref_code.ref_type=ORG_NATURE。';
COMMENT ON COLUMN whale.org_unit.name_zh IS '组织中文名称。';
COMMENT ON COLUMN whale.org_unit.name_en IS '组织英文名称。';
COMMENT ON COLUMN whale.org_unit.description_zh IS '组织中文说明。';
COMMENT ON COLUMN whale.org_unit.description_en IS '组织英文说明。';
COMMENT ON COLUMN whale.org_unit.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.org_unit.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.org_unit.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.org_unit.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.org_unit.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.org_unit.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.org_unit.created_by IS '记录创建人或系统账号。';

CREATE TABLE whale.org_power_plant (
    org_power_plant_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    owning_org_unit_id BIGINT NOT NULL REFERENCES whale.org_unit(org_unit_id),
    plant_identifier TEXT NOT NULL,
    plant_type_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    wind_installed_capacity_mw NUMERIC(12,3) NOT NULL DEFAULT 0,
    pv_installed_capacity_mw NUMERIC(12,3) NOT NULL DEFAULT 0,
    storage_power_mw NUMERIC(12,3) NOT NULL DEFAULT 0,
    storage_capacity_mwh NUMERIC(12,3) NOT NULL DEFAULT 0,
    grid_voltage_kv NUMERIC(10,3) NOT NULL,
    grid_capacity_mva NUMERIC(12,3) NOT NULL,
    grid_connection_date DATE,
    dispatch_center TEXT NOT NULL,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(plant_identifier, record_revision)
);
COMMENT ON TABLE whale.org_power_plant IS '【主数据】并网型电场主数据。表示风电、光伏、储能或混合并网场站，是现场工作班组、员工、资产和拓扑的场站上下文。';
COMMENT ON COLUMN whale.org_power_plant.org_power_plant_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.org_power_plant.owning_org_unit_id IS '所属组织单元，表示该并网型电场隶属的公司或管理组织。';
COMMENT ON COLUMN whale.org_power_plant.plant_identifier IS '并网型电场业务稳定标识，不引用 ref_code.code。';
COMMENT ON COLUMN whale.org_power_plant.plant_type_ref_id IS '电场类型，取值来自 ref_code.ref_type=POWER_PLANT_TYPE；统一表示并网型电场，不刻意拆风电场、光伏电场或风光储电场。';
COMMENT ON COLUMN whale.org_power_plant.name_zh IS '电场中文名称。';
COMMENT ON COLUMN whale.org_power_plant.name_en IS '电场英文名称。';
COMMENT ON COLUMN whale.org_power_plant.wind_installed_capacity_mw IS '风机装机容量，单位 MW。';
COMMENT ON COLUMN whale.org_power_plant.pv_installed_capacity_mw IS '光伏装机容量，单位 MW。';
COMMENT ON COLUMN whale.org_power_plant.storage_power_mw IS '储能额定功率，单位 MW。';
COMMENT ON COLUMN whale.org_power_plant.storage_capacity_mwh IS '储能额定容量，单位 MWh。';
COMMENT ON COLUMN whale.org_power_plant.grid_voltage_kv IS '并网电压等级，单位 kV。';
COMMENT ON COLUMN whale.org_power_plant.grid_capacity_mva IS '并网容量，单位 MVA。';
COMMENT ON COLUMN whale.org_power_plant.grid_connection_date IS '并网日期。';
COMMENT ON COLUMN whale.org_power_plant.dispatch_center IS '调度机构或调度中心名称。';
COMMENT ON COLUMN whale.org_power_plant.description_zh IS '电场中文说明。';
COMMENT ON COLUMN whale.org_power_plant.description_en IS '电场英文说明。';
COMMENT ON COLUMN whale.org_power_plant.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.org_power_plant.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.org_power_plant.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.org_power_plant.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.org_power_plant.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.org_power_plant.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.org_power_plant.created_by IS '记录创建人或系统账号。';

