COMMENT ON COLUMN whale.sec_permission.name_zh IS '权限中文名称。';
COMMENT ON COLUMN whale.sec_permission.name_en IS '权限英文名称。';
COMMENT ON COLUMN whale.sec_permission.description_zh IS '权限中文说明。';
COMMENT ON COLUMN whale.sec_permission.description_en IS '权限英文说明。';
COMMENT ON COLUMN whale.sec_permission.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.sec_permission.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
