CREATE TABLE whale.ast_asset (
    ast_asset_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    power_plant_id BIGINT NOT NULL REFERENCES whale.org_power_plant(org_power_plant_id),
    model_id BIGINT NOT NULL REFERENCES whale.ast_asset_model(ast_asset_model_id),
    parent_asset_id BIGINT REFERENCES whale.ast_asset(ast_asset_id),
    asset_identifier TEXT NOT NULL,
    asset_type_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    serial_number TEXT,
    production_date DATE,
    installation_date DATE,
    commissioning_date DATE,
    asset_lifecycle_status_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(asset_identifier, record_revision)
);
