COMMENT ON COLUMN whale.ast_asset.description_zh IS '资产中文说明。';
COMMENT ON COLUMN whale.ast_asset.description_en IS '资产英文说明。';
COMMENT ON COLUMN whale.ast_asset.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.ast_asset.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.ast_asset.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.ast_asset.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.ast_asset.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
