CREATE TABLE whale.ast_asset_maintenance_event (
    ast_asset_maintenance_event_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    asset_id BIGINT NOT NULL REFERENCES whale.ast_asset(ast_asset_id),
    event_type_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    event_status_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    occurred_at TIMESTAMPTZ NOT NULL,
    completed_at TIMESTAMPTZ,
    title_zh TEXT NOT NULL,
    title_en TEXT NOT NULL,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    old_asset_id BIGINT REFERENCES whale.ast_asset(ast_asset_id),
    new_asset_id BIGINT REFERENCES whale.ast_asset(ast_asset_id),
    work_order_identifier TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system'
