COMMENT ON COLUMN whale.ast_asset_maintenance_event.event_status_ref_id IS '事件状态，取值来自 ref_code.ref_type=EVENT_STATUS。';
COMMENT ON COLUMN whale.ast_asset_maintenance_event.occurred_at IS '事件发生时间。';
COMMENT ON COLUMN whale.ast_asset_maintenance_event.completed_at IS '事件完成时间；未完成时为空。';
