COMMENT ON COLUMN whale.ast_asset_maintenance_event.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.ast_asset_maintenance_event.created_by IS '记录创建人或系统账号。';

CREATE TABLE whale.geo_location (
