    coordinate_y NUMERIC(14,4),
    height_m NUMERIC(12,3),
    rotation_x NUMERIC(10,4) NOT NULL DEFAULT 0,
    rotation_y NUMERIC(10,4) NOT NULL DEFAULT 0,
    rotation_z NUMERIC(10,4) NOT NULL DEFAULT 0,
    scale_x NUMERIC(10,4) NOT NULL DEFAULT 1,
    scale_y NUMERIC(10,4) NOT NULL DEFAULT 1,
    scale_z NUMERIC(10,4) NOT NULL DEFAULT 1,
    model_file_name TEXT,
    model_file_format_ref_id BIGINT REFERENCES whale.ref_code(ref_code_id),
    model_object_identifier TEXT,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(location_identifier, record_revision)
);
COMMENT ON TABLE whale.geo_location IS '【主数据】三维场景资产位置主数据。只保存需要在三维图上显示的大型真实资产位置，不保存接口、拓扑边或普通小部件位置。';
COMMENT ON COLUMN whale.geo_location.geo_location_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.geo_location.asset_id IS '三维场景位置对应的真实资产，不能为空。';
COMMENT ON COLUMN whale.geo_location.location_identifier IS '位置业务稳定标识，不引用 ref_code.code。';
COMMENT ON COLUMN whale.geo_location.coordinate_system IS '坐标系名称，例如 WGS84、CGCS2000、LOCAL_SITE。';
COMMENT ON COLUMN whale.geo_location.longitude IS '经度，适用于地理坐标系。';
COMMENT ON COLUMN whale.geo_location.latitude IS '纬度，适用于地理坐标系。';
COMMENT ON COLUMN whale.geo_location.altitude_m IS '高程或海拔，单位米。';
COMMENT ON COLUMN whale.geo_location.coordinate_x IS '场站平面坐标或投影坐标 X。';
COMMENT ON COLUMN whale.geo_location.coordinate_y IS '场站平面坐标或投影坐标 Y。';
COMMENT ON COLUMN whale.geo_location.height_m IS '设备本体高度，单位米，例如风机轮毂高度、测风塔高度、主变外形高度。';
COMMENT ON COLUMN whale.geo_location.rotation_x IS '三维模型绕 X 轴旋转角，单位度。';
COMMENT ON COLUMN whale.geo_location.rotation_y IS '三维模型绕 Y 轴旋转角，单位度。';
COMMENT ON COLUMN whale.geo_location.rotation_z IS '三维模型绕 Z 轴旋转角，单位度。';
COMMENT ON COLUMN whale.geo_location.scale_x IS '三维模型 X 方向缩放系数。';
COMMENT ON COLUMN whale.geo_location.scale_y IS '三维模型 Y 方向缩放系数。';
COMMENT ON COLUMN whale.geo_location.scale_z IS '三维模型 Z 方向缩放系数。';
COMMENT ON COLUMN whale.geo_location.model_file_name IS '三维模型文件名，例如 glTF、FBX、OBJ 模型文件。';
COMMENT ON COLUMN whale.geo_location.model_file_format_ref_id IS '模型文件格式，取值来自 ref_code.ref_type=MODEL_FILE_FORMAT。';
COMMENT ON COLUMN whale.geo_location.model_object_identifier IS '模型文件内部对象标识，用于定位模型内子对象。';
COMMENT ON COLUMN whale.geo_location.description_zh IS '位置中文说明。';
COMMENT ON COLUMN whale.geo_location.description_en IS '位置英文说明。';
COMMENT ON COLUMN whale.geo_location.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.geo_location.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.geo_location.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.geo_location.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.geo_location.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.geo_location.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.geo_location.created_by IS '记录创建人或系统账号。';


CREATE TABLE whale.cfg_protocol_table_registry (
