COMMENT ON COLUMN whale.cfg_protocol_table_registry.table_schema IS '协议物理表所在 schema。';
COMMENT ON COLUMN whale.cfg_protocol_table_registry.table_name IS '协议实际数据库对象名；可为表或执行视图，必须与 PostgreSQL 中真实对象名一致。';
