COMMENT ON COLUMN whale.cfg_protocol_table_registry.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_protocol_table_registry.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.cfg_protocol_table_registry.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
