CREATE TABLE whale.cfg_iec104_type_def (
    cfg_iec104_type_def_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    type_id_ref_id BIGINT NOT NULL UNIQUE REFERENCES whale.ref_code(ref_code_id),
    type_id_value SMALLINT NOT NULL UNIQUE,
    type_category_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    information_value_type_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    time_tag_type_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    point_registration_supported BOOLEAN NOT NULL,
    general_interrogation_supported BOOLEAN NOT NULL DEFAULT FALSE,
    counter_interrogation_supported BOOLEAN NOT NULL DEFAULT FALSE,
    periodic_transmission_supported BOOLEAN NOT NULL DEFAULT FALSE,
    spontaneous_transmission_supported BOOLEAN NOT NULL DEFAULT FALSE,
    command_mode_supported BOOLEAN NOT NULL DEFAULT FALSE,
    related_io_supported BOOLEAN NOT NULL DEFAULT FALSE,
    sort_order INTEGER NOT NULL DEFAULT 0,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    CONSTRAINT chk_cfg_iec104_type_def_value CHECK (type_id_value BETWEEN 0 AND 255)
);
COMMENT ON TABLE whale.cfg_iec104_type_def IS '【元数据】iec104-python 当前公开 c104.Type 的完整 Type ID 元数据。集中保存标准数值、类别、值结构、时标及当前包实际支持能力，禁止依赖 M_/C_ 前缀或数值区间临时推断。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.cfg_iec104_type_def_id IS '自增代理主键。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.type_id_ref_id IS 'IEC104 Type ID 参考代码，必须引用 ref_code.ref_type=IEC104_TYPE_ID。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.type_id_value IS 'IEC 60870-5-104 Type Identification 数值。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.type_category_ref_id IS 'Type ID 类别，引用 ref_code.ref_type=IEC104_TYPE_CATEGORY。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.information_value_type_ref_id IS '信息元素值结构，引用 ref_code.ref_type=IEC104_INFORMATION_VALUE_TYPE。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.time_tag_type_ref_id IS '时标类型，引用 ref_code.ref_type=IEC104_TIME_TAG_TYPE。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.point_registration_supported IS '当前 iec104-python 是否允许作为 c104.Point 注册；系统命令和初始化通知通常为否。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.general_interrogation_supported IS '当前 iec104-python Server 的 QOI=20 站总召实现是否会发送该 Type ID。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.counter_interrogation_supported IS '是否属于当前包累计量召唤处理范围。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.periodic_transmission_supported IS '是否可作为普通 Point 参与 report_ms 周期上送。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.spontaneous_transmission_supported IS '是否可由适配器检测变化后使用 SPONTANEOUS COT 发送。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.command_mode_supported IS '是否适用 c104.CommandMode 的 DIRECT 或 SELECT_AND_EXECUTE。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.related_io_supported IS '是否适用 related_io_address 与 related_io_autoreturn。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.sort_order IS '显示顺序，默认与 Type ID 数值一致。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.enabled IS '是否启用该 Type ID 元数据。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.created_at IS '创建时间。';
COMMENT ON COLUMN whale.cfg_iec104_type_def.created_by IS '创建人或系统账号。';

CREATE OR REPLACE FUNCTION whale.validate_iec104_type_def()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.type_id_ref_id) IS DISTINCT FROM 'IEC104_TYPE_ID' THEN
        RAISE EXCEPTION 'cfg_iec104_type_def.type_id_ref_id must reference IEC104_TYPE_ID';
    END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.type_category_ref_id) IS DISTINCT FROM 'IEC104_TYPE_CATEGORY' THEN
        RAISE EXCEPTION 'cfg_iec104_type_def.type_category_ref_id must reference IEC104_TYPE_CATEGORY';
    END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.information_value_type_ref_id) IS DISTINCT FROM 'IEC104_INFORMATION_VALUE_TYPE' THEN
        RAISE EXCEPTION 'cfg_iec104_type_def.information_value_type_ref_id must reference IEC104_INFORMATION_VALUE_TYPE';
    END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.time_tag_type_ref_id) IS DISTINCT FROM 'IEC104_TIME_TAG_TYPE' THEN
        RAISE EXCEPTION 'cfg_iec104_type_def.time_tag_type_ref_id must reference IEC104_TIME_TAG_TYPE';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_iec104_type_def_validate
BEFORE INSERT OR UPDATE ON whale.cfg_iec104_type_def
FOR EACH ROW EXECUTE FUNCTION whale.validate_iec104_type_def();

CREATE TABLE whale.cfg_iec104_point_item (
    cfg_iec104_point_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cfg_iec104_point_table_id BIGINT NOT NULL REFERENCES whale.cfg_iec104_point_table(cfg_iec104_point_table_id),
    measurement_semantic_id BIGINT NOT NULL REFERENCES whale.cfg_measurement_semantic(cfg_measurement_semantic_id),
    point_identifier TEXT NOT NULL,
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    type_id_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    common_address INTEGER NOT NULL,
    information_object_address INTEGER NOT NULL,
    command_mode_ref_id BIGINT REFERENCES whale.ref_code(ref_code_id),
    report_ms INTEGER NOT NULL DEFAULT 0,
    spontaneous_deadband NUMERIC(24,8) NOT NULL DEFAULT 0,
    spontaneous_min_interval_ms INTEGER NOT NULL DEFAULT 0,
    related_io_address INTEGER,
    related_io_autoreturn BOOLEAN NOT NULL DEFAULT FALSE,
    quality_descriptor_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    protocol_data_type_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    engineering_unit_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    scale_factor NUMERIC(18,8) NOT NULL DEFAULT 1,
    offset_value NUMERIC(18,8) NOT NULL DEFAULT 0,
    value_min NUMERIC(24,8) DEFAULT -1000000,
    value_max NUMERIC(24,8) DEFAULT 1000000,
    allowed_values TEXT,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    CONSTRAINT chk_cfg_iec104_point_item_address CHECK (common_address BETWEEN 1 AND 65534 AND information_object_address BETWEEN 0 AND 16777215),
    CONSTRAINT chk_cfg_iec104_point_item_report_ms CHECK (report_ms >= 0),
    CONSTRAINT chk_cfg_iec104_point_item_spontaneous CHECK (spontaneous_deadband >= 0 AND spontaneous_min_interval_ms >= 0),
    CONSTRAINT chk_cfg_iec104_point_item_related_io CHECK (related_io_address IS NULL OR related_io_address BETWEEN 0 AND 16777215),
    CONSTRAINT chk_cfg_iec104_point_item_autoreturn CHECK (NOT related_io_autoreturn OR related_io_address IS NOT NULL),
    CONSTRAINT chk_cfg_iec104_point_item_not_self_related CHECK (related_io_address IS NULL OR related_io_address <> information_object_address),
    CONSTRAINT chk_cfg_iec104_point_item_value_range CHECK (value_min IS NULL OR value_max IS NULL OR value_min <= value_max),
    CONSTRAINT chk_cfg_iec104_point_item_value_domain CHECK ((value_min IS NOT NULL AND value_max IS NOT NULL) OR allowed_values IS NOT NULL),
    UNIQUE(cfg_iec104_point_table_id, point_identifier, record_revision)
);
CREATE UNIQUE INDEX uq_cfg_iec104_point_item_current_address
ON whale.cfg_iec104_point_item(cfg_iec104_point_table_id, common_address, information_object_address)
WHERE enabled = TRUE AND valid_to IS NULL;
COMMENT ON TABLE whale.cfg_iec104_point_item IS '【配置数据】IEC104 点位定义。记录 CA、IOA、Type ID、解析换算参数和业务语义；COT 属于运行时报文原因，不作为点位固定属性。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.cfg_iec104_point_item_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.cfg_iec104_point_table_id IS '所属 IEC104 设备能力点表。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.measurement_semantic_id IS '协议点对应的业务测量、状态、控制或发布语义。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.point_identifier IS '协议点业务稳定标识，不引用 ref_code.code。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.name_zh IS '协议点中文名称。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.name_en IS '协议点英文名称。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.type_id_ref_id IS 'IEC104 ASDU Type ID，必须存在于 cfg_iec104_type_def；类别与能力不得通过 M_/C_ 前缀推断。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.common_address IS 'ASDU 公共地址 CA；与 Type ID、IOA 共同定位点位。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.information_object_address IS '信息对象地址 IOA；报文不携带业务字段名，通信双方通过 CA、Type ID、IOA 与点表约定解释语义。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.command_mode_ref_id IS 'c104.CommandMode；控制点可取 DIRECT 或 SELECT_AND_EXECUTE，监视点必须为空。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.report_ms IS '传入 Station.add_point(report_ms=...) 的周期上送间隔，单位毫秒；0 表示不启用 iec104-python 内置周期上送。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.spontaneous_deadband IS '适配器自发上送变化判据的绝对死区；iec104-python 不内置变化检测。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.spontaneous_min_interval_ms IS '自发上送最小发送间隔，单位毫秒；0 表示不启用自发上送。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.related_io_address IS '控制点关联的同一 Point Table、同一 CA 下监视点 IOA，用于命令成功后的状态返送。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.related_io_autoreturn IS '是否将 related_io_autoreturn=True 传入 c104；为真时 related_io_address 必填。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.quality_descriptor_enabled IS '是否解析或生成 IEC104 质量描述位。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.protocol_data_type_ref_id IS '协议原始数据类型，取值来自 ref_code.ref_type=PROTOCOL_DATA_TYPE。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.engineering_unit_ref_id IS '协议点工程值单位，取值来自 ref_code.ref_type=UNIT；value_min、value_max 与 allowed_values 均按该单位解释。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.scale_factor IS '协议原始值转换为统一值的比例系数。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.offset_value IS '协议原始值转换为统一值的偏移量。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.value_min IS '该协议点工程值允许下限；为空表示不声明下限。复杂质量规则由模块代码处理。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.value_max IS '该协议点工程值允许上限；为空表示不声明上限。复杂质量规则由模块代码处理。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.allowed_values IS '该协议点离散工程值允许集合，使用逗号分割字符串表达；为空表示不声明离散值集合。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.description_zh IS '协议点中文说明。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.description_en IS '协议点英文说明。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.cfg_iec104_point_item.created_by IS '记录创建人或系统账号。';

CREATE OR REPLACE FUNCTION whale.validate_iec104_point_item_type()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_type RECORD;
    v_command_mode_code TEXT;
    v_related_type_category TEXT;
BEGIN
    SELECT td.*, category.code AS type_category
      INTO v_type
      FROM whale.cfg_iec104_type_def td
      JOIN whale.ref_code category ON category.ref_code_id=td.type_category_ref_id
     WHERE td.type_id_ref_id=NEW.type_id_ref_id
       AND td.enabled=TRUE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'cfg_iec104_point_item.type_id_ref_id % is not enabled in cfg_iec104_type_def', NEW.type_id_ref_id;
    END IF;
    IF NOT v_type.point_registration_supported THEN
        RAISE EXCEPTION 'IEC104 Type ID % cannot be registered as c104.Point', NEW.type_id_ref_id;
    END IF;

    IF NEW.command_mode_ref_id IS NOT NULL THEN
        SELECT code INTO v_command_mode_code
          FROM whale.ref_code
         WHERE ref_code_id=NEW.command_mode_ref_id
           AND ref_type='IEC104_COMMAND_MODE';
        IF NOT FOUND THEN
            RAISE EXCEPTION 'command_mode_ref_id must reference IEC104_COMMAND_MODE';
        END IF;
        IF NOT v_type.command_mode_supported THEN
            RAISE EXCEPTION 'command_mode is not supported by the selected IEC104 Type ID';
        END IF;
    ELSIF v_type.command_mode_supported THEN
        RAISE EXCEPTION 'command_mode_ref_id is required for IEC104 command Point';
    END IF;

    IF NEW.report_ms > 0 AND NOT v_type.periodic_transmission_supported THEN
        RAISE EXCEPTION 'report_ms is not supported by the selected IEC104 Type ID';
    END IF;
    IF NEW.spontaneous_min_interval_ms > 0 AND NOT v_type.spontaneous_transmission_supported THEN
        RAISE EXCEPTION 'spontaneous transmission is not supported by the selected IEC104 Type ID';
    END IF;

    IF NEW.related_io_address IS NOT NULL THEN
        IF NOT v_type.related_io_supported THEN
            RAISE EXCEPTION 'related_io_address is not supported by the selected IEC104 Type ID';
        END IF;
        SELECT category.code INTO v_related_type_category
          FROM whale.cfg_iec104_point_item related
          JOIN whale.cfg_iec104_type_def related_def ON related_def.type_id_ref_id=related.type_id_ref_id
          JOIN whale.ref_code category ON category.ref_code_id=related_def.type_category_ref_id
         WHERE related.cfg_iec104_point_table_id=NEW.cfg_iec104_point_table_id
           AND related.common_address=NEW.common_address
           AND related.information_object_address=NEW.related_io_address
           AND related.enabled=TRUE AND related.valid_to IS NULL;
        IF NOT FOUND OR v_related_type_category NOT IN ('PROCESS_MONITOR','COUNTER_MONITOR','PROTECTION_MONITOR') THEN
            RAISE EXCEPTION 'related_io_address must reference an enabled monitoring Point in the same point table and common address';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE CONSTRAINT TRIGGER trg_cfg_iec104_point_item_type
AFTER INSERT OR UPDATE ON whale.cfg_iec104_point_item
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION whale.validate_iec104_point_item_type();

