COMMENT ON TABLE whale.cfg_iec101_conn IS '【配置数据】IEC101 连接参数。保存协议专属连接参数，通用身份、资产归属和协议类型由 cfg_connection 表表达。';
COMMENT ON COLUMN whale.cfg_iec101_conn.cfg_iec101_conn_id IS '协议连接参数表主键，同时外键引用通用连接父表 cfg_connection。';
COMMENT ON COLUMN whale.cfg_iec101_conn.cfg_iec101_point_table_id IS 'IEC101 设备能力点表。';
COMMENT ON COLUMN whale.cfg_iec101_conn.serial_port IS '串口名称。';
COMMENT ON COLUMN whale.cfg_iec101_conn.baud_rate IS '串口波特率。';
COMMENT ON COLUMN whale.cfg_iec101_conn.link_address IS '链路地址。';
COMMENT ON COLUMN whale.cfg_iec101_conn.common_address IS '默认公共地址。';
COMMENT ON COLUMN whale.cfg_iec101_conn.balanced_mode IS '是否平衡式传输。';
COMMENT ON COLUMN whale.cfg_iec101_conn.timeout_ms IS '协议请求或会话超时时间，单位毫秒。';
COMMENT ON COLUMN whale.cfg_iec101_conn.description_zh IS 'IEC101 连接参数中文说明。';
COMMENT ON COLUMN whale.cfg_iec101_conn.description_en IS 'IEC101 连接参数英文说明。';
COMMENT ON COLUMN whale.cfg_iec101_conn.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.cfg_iec101_conn.created_by IS '记录创建人或系统账号。';

CREATE TABLE whale.cfg_iec104_conn (
    cfg_iec104_conn_id BIGINT PRIMARY KEY REFERENCES whale.cfg_connection(cfg_connection_id),
    cfg_iec104_point_table_id BIGINT NOT NULL REFERENCES whale.cfg_iec104_point_table(cfg_iec104_point_table_id),
    station_role_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    host INET NOT NULL,
    port INTEGER NOT NULL DEFAULT 2404,
    common_address INTEGER NOT NULL,
    t0_ms INTEGER NOT NULL DEFAULT 30000,
    t1_ms INTEGER NOT NULL DEFAULT 15000,
    t2_ms INTEGER NOT NULL DEFAULT 10000,
    t3_ms INTEGER NOT NULL DEFAULT 20000,
    k_value INTEGER NOT NULL DEFAULT 12,
    w_value INTEGER NOT NULL DEFAULT 8,
    timeout_ms INTEGER NOT NULL DEFAULT 5000,
    reconnect_enabled BOOLEAN NOT NULL DEFAULT TRUE,
    reconnect_interval_ms INTEGER NOT NULL DEFAULT 5000,
    max_client_count INTEGER NOT NULL DEFAULT 1,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    CONSTRAINT chk_cfg_iec104_conn_port CHECK (port BETWEEN 1 AND 65535),
    CONSTRAINT chk_cfg_iec104_conn_common_address CHECK (common_address BETWEEN 1 AND 65534),
    CONSTRAINT chk_cfg_iec104_conn_timers CHECK (t0_ms > 0 AND t1_ms > 0 AND t2_ms > 0 AND t3_ms > 0 AND timeout_ms > 0),
    CONSTRAINT chk_cfg_iec104_conn_windows CHECK (k_value > 0 AND w_value > 0 AND w_value <= k_value),
    CONSTRAINT chk_cfg_iec104_conn_reconnect CHECK ((reconnect_enabled AND reconnect_interval_ms > 0) OR (NOT reconnect_enabled AND reconnect_interval_ms >= 0)),
    CONSTRAINT chk_cfg_iec104_conn_max_client_count CHECK (max_client_count > 0)
);
COMMENT ON TABLE whale.cfg_iec104_conn IS '【配置数据】IEC104 连接参数。只保存 TCP/APCI、站端角色、连接恢复和监听容量等连接级信息；总召、发布、接收与控制行为由 task 模型表达。';
COMMENT ON COLUMN whale.cfg_iec104_conn.cfg_iec104_conn_id IS '协议连接参数表主键，同时外键引用通用连接父表 cfg_connection。';
COMMENT ON COLUMN whale.cfg_iec104_conn.cfg_iec104_point_table_id IS 'IEC104 设备能力点表。';
COMMENT ON COLUMN whale.cfg_iec104_conn.station_role_ref_id IS '本系统 IEC104 站端角色，取值来自 ref_code.ref_type=IEC104_STATION_ROLE。';
COMMENT ON COLUMN whale.cfg_iec104_conn.host IS '角色相关地址：控制站表示远端子站地址；被控站表示本地监听地址。';
COMMENT ON COLUMN whale.cfg_iec104_conn.port IS '角色相关 TCP 端口：控制站表示远端端口；被控站表示本地监听端口。';
COMMENT ON COLUMN whale.cfg_iec104_conn.common_address IS '默认 ASDU 公共地址；具体点位仍以 cfg_iec104_point_item.common_address 为准。';
COMMENT ON COLUMN whale.cfg_iec104_conn.t0_ms IS '建立连接超时时间。';
COMMENT ON COLUMN whale.cfg_iec104_conn.t1_ms IS '发送或测试确认超时时间。';
COMMENT ON COLUMN whale.cfg_iec104_conn.t2_ms IS '无数据确认超时时间。';
COMMENT ON COLUMN whale.cfg_iec104_conn.t3_ms IS '空闲测试间隔。';
COMMENT ON COLUMN whale.cfg_iec104_conn.k_value IS '未确认 I-format 发送窗口上限 k。';
COMMENT ON COLUMN whale.cfg_iec104_conn.w_value IS '收到 I-format 后触发确认的接收窗口阈值 w。';
COMMENT ON COLUMN whale.cfg_iec104_conn.timeout_ms IS '连接级默认协议超时时间，单位毫秒。';
COMMENT ON COLUMN whale.cfg_iec104_conn.reconnect_enabled IS '控制站断线后是否自动重连；被控站角色通常忽略。';
COMMENT ON COLUMN whale.cfg_iec104_conn.reconnect_interval_ms IS '控制站重连间隔，单位毫秒。';
COMMENT ON COLUMN whale.cfg_iec104_conn.max_client_count IS '被控站允许同时接入的控制站 TCP 会话上限；控制站角色通常忽略。';
COMMENT ON COLUMN whale.cfg_iec104_conn.description_zh IS 'IEC104 连接参数中文说明。';
COMMENT ON COLUMN whale.cfg_iec104_conn.description_en IS 'IEC104 连接参数英文说明。';
COMMENT ON COLUMN whale.cfg_iec104_conn.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.cfg_iec104_conn.created_by IS '记录创建人或系统账号。';

CREATE OR REPLACE FUNCTION whale.validate_iec104_conn_role()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE v_ref_type TEXT;
BEGIN
    SELECT ref_type INTO v_ref_type FROM whale.ref_code WHERE ref_code_id = NEW.station_role_ref_id;
    IF v_ref_type IS DISTINCT FROM 'IEC104_STATION_ROLE' THEN
        RAISE EXCEPTION 'cfg_iec104_conn.station_role_ref_id must reference IEC104_STATION_ROLE; ref_id=% ref_type=%', NEW.station_role_ref_id, COALESCE(v_ref_type, '<missing>');
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_iec104_conn_role
BEFORE INSERT OR UPDATE ON whale.cfg_iec104_conn
FOR EACH ROW EXECUTE FUNCTION whale.validate_iec104_conn_role();

