CREATE TABLE whale.cfg_iec61850_mms_point_item (
    cfg_iec61850_mms_point_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    cfg_iec61850_mms_point_table_id BIGINT NOT NULL REFERENCES whale.cfg_iec61850_mms_point_table(cfg_iec61850_mms_point_table_id),
    measurement_semantic_id BIGINT NOT NULL REFERENCES whale.cfg_measurement_semantic(cfg_measurement_semantic_id),
    point_identifier TEXT NOT NULL,
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    object_reference TEXT NOT NULL,
    logical_device TEXT,
    logical_node TEXT,
    data_object TEXT,
