COMMENT ON COLUMN whale.cfg_ads_point_item.offset_value IS '协议原始值转换为统一值的偏移量。';
COMMENT ON COLUMN whale.cfg_ads_point_item.value_min IS '该协议点工程值允许下限；为空表示不声明下限。复杂质量规则由模块代码处理。';
COMMENT ON COLUMN whale.cfg_ads_point_item.value_max IS '该协议点工程值允许上限；为空表示不声明上限。复杂质量规则由模块代码处理。';
COMMENT ON COLUMN whale.cfg_ads_point_item.allowed_values IS '该协议点离散工程值允许集合，使用逗号分割字符串表达；为空表示不声明离散值集合。';
COMMENT ON COLUMN whale.cfg_ads_point_item.description_zh IS '协议点中文说明。';
COMMENT ON COLUMN whale.cfg_ads_point_item.description_en IS '协议点英文说明。';
COMMENT ON COLUMN whale.cfg_ads_point_item.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_ads_point_item.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.cfg_ads_point_item.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_ads_point_item.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.cfg_ads_point_item.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.cfg_ads_point_item.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.cfg_ads_point_item.created_by IS '记录创建人或系统账号。';

CREATE TABLE whale.cfg_ads_conn (
    cfg_ads_conn_id BIGINT PRIMARY KEY REFERENCES whale.cfg_connection(cfg_connection_id),
    cfg_ads_point_table_id BIGINT NOT NULL REFERENCES whale.cfg_ads_point_table(cfg_ads_point_table_id),
    host INET NOT NULL,
    ams_net_id TEXT NOT NULL,
    ams_port INTEGER NOT NULL DEFAULT 851,
    route_name TEXT NOT NULL,
    timeout_ms INTEGER NOT NULL DEFAULT 5000,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system'
);
COMMENT ON TABLE whale.cfg_ads_conn IS '【配置数据】ADS 连接参数。保存协议专属连接参数，通用身份、资产归属和协议类型由 cfg_connection 表表达。';
COMMENT ON COLUMN whale.cfg_ads_conn.cfg_ads_conn_id IS '协议连接参数表主键，同时外键引用通用连接父表 cfg_connection。';
COMMENT ON COLUMN whale.cfg_ads_conn.cfg_ads_point_table_id IS 'ADS 设备能力点表。';
COMMENT ON COLUMN whale.cfg_ads_conn.host IS 'ADS 设备 IP。';
COMMENT ON COLUMN whale.cfg_ads_conn.ams_net_id IS 'AMS Net ID。';
COMMENT ON COLUMN whale.cfg_ads_conn.ams_port IS 'AMS 端口。';
COMMENT ON COLUMN whale.cfg_ads_conn.route_name IS 'ADS 路由名称。';
COMMENT ON COLUMN whale.cfg_ads_conn.timeout_ms IS '协议请求或会话超时时间，单位毫秒。';
COMMENT ON COLUMN whale.cfg_ads_conn.description_zh IS 'ADS 连接参数中文说明。';
COMMENT ON COLUMN whale.cfg_ads_conn.description_en IS 'ADS 连接参数英文说明。';
COMMENT ON COLUMN whale.cfg_ads_conn.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.cfg_ads_conn.created_by IS '记录创建人或系统账号。';


CREATE TABLE whale.cfg_protocol_operation_def (
    cfg_protocol_operation_def_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    protocol_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    operation_identifier TEXT NOT NULL,
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    native_operation_code TEXT,
    native_operation_name TEXT NOT NULL,
    operation_semantic_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    operation_direction_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    request_response_mode_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    standard_ref TEXT NOT NULL,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(protocol_ref_id, operation_identifier, record_revision)
);
COMMENT ON TABLE whale.cfg_protocol_operation_def IS '【元数据】协议原生操作定义表。描述各通信协议的原生读、写、控制、发布、订阅、报告、通知、总召、时钟同步等操作语义，不直接作为平台任务类型。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.cfg_protocol_operation_def_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.protocol_ref_id IS '协议类型，取值来自 ref_code.ref_type=PROTOCOL。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.operation_identifier IS '协议原生操作业务稳定标识，不引用 ref_code.code。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.name_zh IS '协议原生操作中文名称。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.name_en IS '协议原生操作英文名称。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.native_operation_code IS '协议标准中的原生操作码、功能码、ASDU 类型、COT、服务名或工程码；没有固定码值时可为空。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.native_operation_name IS '协议标准或工程语境中的原生操作名称。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.operation_semantic_ref_id IS '协议操作语义，取值来自 ref_code.ref_type=PROTOCOL_OPERATION_SEMANTIC。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.operation_direction_ref_id IS '协议原生操作方向，取值来自 ref_code.ref_type=PROTOCOL_OPERATION_DIRECTION。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.request_response_mode_ref_id IS '协议交互模式，取值来自 ref_code.ref_type=REQUEST_RESPONSE_MODE。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.standard_ref IS '协议标准、规范条款或工程来源说明。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.description_zh IS '协议原生操作中文说明。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.description_en IS '协议原生操作英文说明。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.cfg_protocol_operation_def.created_by IS '记录创建人或系统账号。';

CREATE TABLE whale.cfg_protocol_operation_role (
    cfg_protocol_operation_role_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    protocol_operation_def_id BIGINT NOT NULL REFERENCES whale.cfg_protocol_operation_def(cfg_protocol_operation_def_id),
    protocol_role_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    point_table_usage_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    allowed BOOLEAN NOT NULL DEFAULT TRUE,
    requires_point_table BOOLEAN NOT NULL DEFAULT TRUE,
    requires_write_value BOOLEAN NOT NULL DEFAULT FALSE,
    requires_response_mapping BOOLEAN NOT NULL DEFAULT FALSE,
    requires_confirm BOOLEAN NOT NULL DEFAULT FALSE,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(protocol_operation_def_id, protocol_role_ref_id, record_revision)
);
CREATE UNIQUE INDEX uq_cfg_protocol_operation_role_current
ON whale.cfg_protocol_operation_role(protocol_operation_def_id, protocol_role_ref_id)
WHERE enabled = TRUE AND valid_to IS NULL;
COMMENT ON TABLE whale.cfg_protocol_operation_role IS '【元数据】协议原生操作与协议角色合法组合。使用各协议规范中的角色名称，不再映射为平台通用任务类型。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.cfg_protocol_operation_role_id IS '协议操作—角色组合主键。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.protocol_operation_def_id IS '协议原生操作定义。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.protocol_role_ref_id IS '协议角色，取值来自 ref_code.ref_type=PROTOCOL_ROLE，code 必须带协议命名空间。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.point_table_usage_ref_id IS '该操作角色组合要求的任务点表用途，取值来自 ref_code.ref_type=POINT_TABLE_USAGE。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.allowed IS '该协议原生操作与协议角色组合是否允许注册任务。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.requires_point_table IS '任务是否必须绑定非空 task_point_table。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.requires_write_value IS '任务是否需要写入值、控制值、命令载荷或方法入参。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.requires_response_mapping IS '任务是否需要响应字段、回读字段或上送字段映射。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.requires_confirm IS '任务是否需要协议确认、业务确认或写后校验。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.description_zh IS '组合中文说明。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.description_en IS '组合英文说明。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.record_revision IS '追加式不可变快照修订号。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.supersedes_id IS '上一版记录主键。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.enabled IS '是否为当前启用记录。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.valid_from IS '生效开始时间。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.valid_to IS '失效时间；为空表示当前有效。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.created_at IS '创建时间。';
COMMENT ON COLUMN whale.cfg_protocol_operation_role.created_by IS '创建人。';

CREATE OR REPLACE FUNCTION whale.validate_cfg_protocol_operation_role_refs()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.protocol_role_ref_id) IS DISTINCT FROM 'PROTOCOL_ROLE' THEN
        RAISE EXCEPTION 'protocol_role_ref_id must reference PROTOCOL_ROLE';
    END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.point_table_usage_ref_id) IS DISTINCT FROM 'POINT_TABLE_USAGE' THEN
        RAISE EXCEPTION 'point_table_usage_ref_id must reference POINT_TABLE_USAGE';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_protocol_operation_role_refs
BEFORE INSERT OR UPDATE ON whale.cfg_protocol_operation_role
FOR EACH ROW EXECUTE FUNCTION whale.validate_cfg_protocol_operation_role_refs();


CREATE TABLE whale.task_point_table (
    task_point_table_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    point_table_identifier TEXT NOT NULL,
    point_table_usage_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(point_table_identifier, record_revision)
);
COMMENT ON TABLE whale.task_point_table IS '【配置数据】任务点表表头。表示协议交互任务实际使用的接入点、控制目标、发布字段、响应字段或上报数据集。';
COMMENT ON COLUMN whale.task_point_table.task_point_table_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.task_point_table.point_table_identifier IS '任务点表业务稳定标识，不引用 ref_code.code。';
COMMENT ON COLUMN whale.task_point_table.point_table_usage_ref_id IS '任务点表用途，取值来自 ref_code.ref_type=POINT_TABLE_USAGE。';
COMMENT ON COLUMN whale.task_point_table.name_zh IS '任务点表中文名称。';
COMMENT ON COLUMN whale.task_point_table.name_en IS '任务点表英文名称。';
COMMENT ON COLUMN whale.task_point_table.description_zh IS '任务点表中文说明。';
COMMENT ON COLUMN whale.task_point_table.description_en IS '任务点表英文说明。';
COMMENT ON COLUMN whale.task_point_table.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.task_point_table.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.task_point_table.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.task_point_table.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.task_point_table.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.task_point_table.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.task_point_table.created_by IS '记录创建人或系统账号。';

CREATE TABLE whale.task_point_item (
    task_point_item_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_point_table_id BIGINT NOT NULL REFERENCES whale.task_point_table(task_point_table_id),
    protocol_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    protocol_point_table_id BIGINT NOT NULL,
    protocol_point_item_id BIGINT NOT NULL,
    point_role_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    scan_order INTEGER NOT NULL DEFAULT 0,
    sample_mode_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT,
    enabled BOOLEAN NOT NULL DEFAULT TRUE,
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(task_point_table_id, protocol_ref_id, protocol_point_table_id, protocol_point_item_id, point_role_ref_id, record_revision)
);
COMMENT ON TABLE whale.task_point_item IS '【配置数据】任务点表明细。直接引用协议能力点表中的点项，表达任务实际使用的采集点、写入目标、控制目标、发布字段、响应字段或上报字段。';
COMMENT ON COLUMN whale.task_point_item.task_point_item_id IS '自增代理主键，列名统一为表名_id，满足 SQLAlchemy ORM 映射要求。';
COMMENT ON COLUMN whale.task_point_item.task_point_table_id IS '所属任务点表。';
COMMENT ON COLUMN whale.task_point_item.protocol_ref_id IS '任务点所属协议，取值来自 ref_code.ref_type=PROTOCOL；用于解释 protocol_point_table_id 与 protocol_point_item_id 所对应的协议物理表。';
COMMENT ON COLUMN whale.task_point_item.protocol_point_table_id IS '协议能力点表主键值；需结合 protocol_ref_id 和 cfg_protocol_table_registry 定位对应 cfg_<protocol>_point_table 物理表。';
COMMENT ON COLUMN whale.task_point_item.protocol_point_item_id IS '协议能力点表明细主键值；需结合 protocol_ref_id 和 cfg_protocol_table_registry 定位对应 cfg_<protocol>_point_item 物理表。';
COMMENT ON COLUMN whale.task_point_item.point_role_ref_id IS '点在任务中的角色，取值来自 ref_code.ref_type=TASK_POINT_ROLE。';
COMMENT ON COLUMN whale.task_point_item.scan_order IS '任务内点位处理顺序。';
COMMENT ON COLUMN whale.task_point_item.sample_mode_ref_id IS '任务点采样或触发模式，取值来自 ref_code.ref_type=SAMPLE_MODE。';
COMMENT ON COLUMN whale.task_point_item.description_zh IS '任务点中文说明。';
COMMENT ON COLUMN whale.task_point_item.description_en IS '任务点英文说明。';
COMMENT ON COLUMN whale.task_point_item.record_revision IS '追加式不可变快照修订号。同一业务稳定标识变更时新增记录并递增修订号，不更新旧记录。';
COMMENT ON COLUMN whale.task_point_item.supersedes_id IS '被本记录替代的上一版记录主键；为空表示初始版本。';
COMMENT ON COLUMN whale.task_point_item.enabled IS '是否为当前启用记录。修改状态时应新增记录，不更新旧记录。';
COMMENT ON COLUMN whale.task_point_item.valid_from IS '记录业务生效开始时间。';
COMMENT ON COLUMN whale.task_point_item.valid_to IS '记录业务生效结束时间；为空表示仍然有效。';
COMMENT ON COLUMN whale.task_point_item.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.task_point_item.created_by IS '记录创建人或系统账号。';

CREATE OR REPLACE FUNCTION whale.validate_task_point_item_refs()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.protocol_ref_id) IS DISTINCT FROM 'PROTOCOL' THEN RAISE EXCEPTION 'task_point_item.protocol_ref_id must reference PROTOCOL'; END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.point_role_ref_id) IS DISTINCT FROM 'TASK_POINT_ROLE' THEN RAISE EXCEPTION 'task_point_item.point_role_ref_id must reference TASK_POINT_ROLE'; END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.sample_mode_ref_id) IS DISTINCT FROM 'SAMPLE_MODE' THEN RAISE EXCEPTION 'task_point_item.sample_mode_ref_id must reference SAMPLE_MODE'; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_task_point_item_refs
BEFORE INSERT OR UPDATE ON whale.task_point_item
FOR EACH ROW EXECUTE FUNCTION whale.validate_task_point_item_refs();

CREATE TABLE whale.task (
    task_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_identifier TEXT NOT NULL,
    name_zh TEXT NOT NULL,
    name_en TEXT NOT NULL,
    cfg_connection_id BIGINT NOT NULL REFERENCES whale.cfg_connection(cfg_connection_id),
    protocol_operation_def_id BIGINT NOT NULL REFERENCES whale.cfg_protocol_operation_def(cfg_protocol_operation_def_id),
    protocol_role_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    task_point_table_id BIGINT REFERENCES whale.task_point_table(task_point_table_id),
    trigger_mode_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    timeout_ms INTEGER NOT NULL DEFAULT 5000,
    retry_count INTEGER NOT NULL DEFAULT 3,
    task_status_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    description_zh TEXT NOT NULL,
    description_en TEXT NOT NULL,
    record_revision INTEGER NOT NULL DEFAULT 1,
    supersedes_id BIGINT REFERENCES whale.task(task_id),
    valid_from TIMESTAMPTZ NOT NULL DEFAULT now(),
    valid_to TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    CONSTRAINT chk_task_timeout_positive CHECK (timeout_ms > 0),
    CONSTRAINT chk_task_retry_nonnegative CHECK (retry_count >= 0),
    CONSTRAINT chk_task_valid_period CHECK (valid_to IS NULL OR valid_to > valid_from),
    UNIQUE(task_identifier, record_revision)
);
CREATE UNIQUE INDEX uq_task_current
ON whale.task(task_identifier)
WHERE valid_to IS NULL;
COMMENT ON TABLE whale.task IS '【配置数据】协议交互任务完整版本。一个记录同时保存任务身份、连接、协议原生操作、协议角色、任务点表、触发方式、超时、重试和状态，不再拆分第二张任务配置表。';
COMMENT ON COLUMN whale.task.task_id IS '任务版本主键。';
COMMENT ON COLUMN whale.task.task_identifier IS '跨版本稳定的任务业务标识。';
COMMENT ON COLUMN whale.task.name_zh IS '任务中文名称。';
COMMENT ON COLUMN whale.task.name_en IS '任务英文名称。';
COMMENT ON COLUMN whale.task.cfg_connection_id IS '任务绑定的通用连接主键。';
COMMENT ON COLUMN whale.task.protocol_operation_def_id IS '任务执行的协议原生操作。';
COMMENT ON COLUMN whale.task.protocol_role_ref_id IS '本任务承担的协议角色，取值来自 PROTOCOL_ROLE，并按协议规范命名。';
COMMENT ON COLUMN whale.task.task_point_table_id IS '任务使用或复用的任务点表；操作不需要普通点项时可为空。';
COMMENT ON COLUMN whale.task.trigger_mode_ref_id IS '任务触发方式，取值来自 TRIGGER_MODE。';
COMMENT ON COLUMN whale.task.timeout_ms IS '任务级默认超时时间，单位毫秒。';
COMMENT ON COLUMN whale.task.retry_count IS '任务级默认重试次数。';
COMMENT ON COLUMN whale.task.task_status_ref_id IS '任务状态，取值来自 TASK_STATUS；FAILED 表示因不可恢复错误而失败退出。';
COMMENT ON COLUMN whale.task.description_zh IS '任务中文说明。';
COMMENT ON COLUMN whale.task.description_en IS '任务英文说明。';
COMMENT ON COLUMN whale.task.record_revision IS '任务版本号；同一 task_identifier 从 1 递增。';
COMMENT ON COLUMN whale.task.supersedes_id IS '被当前版本替代的上一版 task_id。';
COMMENT ON COLUMN whale.task.valid_from IS '任务版本生效时间。';
COMMENT ON COLUMN whale.task.valid_to IS '任务版本失效时间；为空表示当前版本。';
COMMENT ON COLUMN whale.task.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.task.created_by IS '记录创建人。';

CREATE OR REPLACE FUNCTION whale.validate_task_refs()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.protocol_role_ref_id) IS DISTINCT FROM 'PROTOCOL_ROLE' THEN
        RAISE EXCEPTION 'task.protocol_role_ref_id must reference PROTOCOL_ROLE';
    END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.trigger_mode_ref_id) IS DISTINCT FROM 'TRIGGER_MODE' THEN
        RAISE EXCEPTION 'task.trigger_mode_ref_id must reference TRIGGER_MODE';
    END IF;
    IF (SELECT ref_type FROM whale.ref_code WHERE ref_code_id=NEW.task_status_ref_id) IS DISTINCT FROM 'TASK_STATUS' THEN
        RAISE EXCEPTION 'task.task_status_ref_id must reference TASK_STATUS';
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_task_refs
BEFORE INSERT OR UPDATE ON whale.task
FOR EACH ROW EXECUTE FUNCTION whale.validate_task_refs();


