CREATE OR REPLACE FUNCTION whale.validate_cfg_value_domain()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE v_data_type_ref_type TEXT;
BEGIN
    SELECT ref_type INTO v_data_type_ref_type
    FROM whale.ref_code WHERE ref_code_id=NEW.data_type_ref_id;
    IF v_data_type_ref_type IS DISTINCT FROM 'DATA_TYPE' THEN
        RAISE EXCEPTION 'cfg_value_domain.data_type_ref_id must reference DATA_TYPE';
    END IF;
    IF NEW.ref_code_type IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM whale.ref_code WHERE ref_type=NEW.ref_code_type
    ) THEN
        RAISE EXCEPTION 'cfg_value_domain.ref_code_type % has no matching ref_code values', NEW.ref_code_type;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_value_domain_validate
BEFORE INSERT OR UPDATE ON whale.cfg_value_domain
FOR EACH ROW EXECUTE FUNCTION whale.validate_cfg_value_domain();

CREATE OR REPLACE FUNCTION whale.validate_cfg_value_domain_item()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE v_code TEXT; v_ref_type TEXT; v_domain_ref_type TEXT;
BEGIN
    SELECT ref_code_type INTO v_domain_ref_type
    FROM whale.cfg_value_domain WHERE cfg_value_domain_id=NEW.cfg_value_domain_id;

    IF v_domain_ref_type IS NULL AND NEW.ref_code_id IS NOT NULL THEN
        RAISE EXCEPTION 'cfg_value_domain_item.ref_code_id must be NULL for a pure-text domain';
    ELSIF v_domain_ref_type IS NOT NULL AND NEW.ref_code_id IS NULL THEN
        RAISE EXCEPTION 'cfg_value_domain_item.ref_code_id is required for ref_code-backed domain type %', v_domain_ref_type;
    END IF;

    IF NEW.ref_code_id IS NOT NULL THEN
        SELECT code, ref_type INTO v_code, v_ref_type
        FROM whale.ref_code WHERE ref_code_id = NEW.ref_code_id;
        IF v_code IS DISTINCT FROM NEW.value_code THEN
            RAISE EXCEPTION 'cfg_value_domain_item.value_code % must equal referenced ref_code.code %', NEW.value_code, v_code;
        END IF;
        IF v_ref_type IS DISTINCT FROM v_domain_ref_type THEN
            RAISE EXCEPTION 'cfg_value_domain_item ref_type % must equal domain ref_code_type %', v_ref_type, v_domain_ref_type;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_value_domain_item_validate
BEFORE INSERT OR UPDATE ON whale.cfg_value_domain_item
FOR EACH ROW EXECUTE FUNCTION whale.validate_cfg_value_domain_item();

CREATE OR REPLACE FUNCTION whale.validate_cfg_task_field_constraint()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_field_code TEXT;
    v_domain_ref_type TEXT;
    v_protocol_code TEXT;
    v_expected_ref_type TEXT;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM whale.cfg_value_domain_item i
        WHERE i.cfg_value_domain_id = NEW.cfg_value_domain_id
          AND i.value_code = NEW.default_value_code
          AND i.enabled = TRUE AND i.valid_to IS NULL
    ) THEN
        RAISE EXCEPTION 'default value % is not a member of cfg_value_domain_id=%', NEW.default_value_code, NEW.cfg_value_domain_id;
    END IF;

    SELECT code INTO v_field_code
    FROM whale.ref_code
    WHERE ref_code_id=NEW.constrained_field_ref_id
      AND ref_type='TASK_CONSTRAINT_FIELD';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'constrained_field_ref_id must reference TASK_CONSTRAINT_FIELD';
    END IF;

    SELECT ref_code_type INTO v_domain_ref_type
    FROM whale.cfg_value_domain
    WHERE cfg_value_domain_id=NEW.cfg_value_domain_id;

    v_expected_ref_type := CASE v_field_code
        WHEN 'TRIGGER_MODE' THEN 'TRIGGER_MODE'
        WHEN 'POINT_ROLE' THEN 'TASK_POINT_ROLE'
        WHEN 'SAMPLE_MODE' THEN 'SAMPLE_MODE'
        ELSE NULL
    END;

    IF v_field_code='PROTOCOL_TYPE_ID' THEN
        SELECT protocol.code INTO v_protocol_code
        FROM whale.cfg_protocol_operation_role r
        JOIN whale.cfg_protocol_operation_def op ON op.cfg_protocol_operation_def_id=r.protocol_operation_def_id
        JOIN whale.ref_code protocol ON protocol.ref_code_id=op.protocol_ref_id
        WHERE r.cfg_protocol_operation_role_id=NEW.cfg_protocol_operation_role_id;
        IF v_protocol_code='IEC104' THEN
            v_expected_ref_type := 'IEC104_TYPE_ID';
        ELSE
            RAISE EXCEPTION 'PROTOCOL_TYPE_ID constraint is not defined for protocol %', v_protocol_code;
        END IF;
    END IF;

    IF v_expected_ref_type IS NULL OR v_domain_ref_type IS DISTINCT FROM v_expected_ref_type THEN
        RAISE EXCEPTION 'constraint field % requires value domain ref_code_type %, actual %',
            v_field_code, v_expected_ref_type, COALESCE(v_domain_ref_type,'<NULL>');
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_task_field_constraint_validate
BEFORE INSERT OR UPDATE ON whale.cfg_task_field_constraint
FOR EACH ROW EXECUTE FUNCTION whale.validate_cfg_task_field_constraint();

CREATE OR REPLACE FUNCTION whale.validate_cfg_task_param_dependency_rule()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    v_operation_role_id BIGINT;
    v_field_type TEXT;
    v_field_code TEXT;
    v_operator_type TEXT;
    v_action_type TEXT;
BEGIN
    SELECT cfg_protocol_operation_role_id INTO v_operation_role_id
    FROM whale.task_param_def
    WHERE task_param_def_id=NEW.target_task_param_def_id;

    SELECT ref_type, code INTO v_field_type, v_field_code
    FROM whale.ref_code WHERE ref_code_id=NEW.condition_field_ref_id;
    SELECT ref_type INTO v_operator_type
    FROM whale.ref_code WHERE ref_code_id=NEW.condition_operator_ref_id;
    SELECT ref_type INTO v_action_type
    FROM whale.ref_code WHERE ref_code_id=NEW.rule_action_ref_id;

    IF v_field_type IS DISTINCT FROM 'TASK_CONSTRAINT_FIELD' THEN
        RAISE EXCEPTION 'condition_field_ref_id must reference TASK_CONSTRAINT_FIELD';
    END IF;
    IF v_operator_type IS DISTINCT FROM 'VALIDATION_OPERATOR' THEN
        RAISE EXCEPTION 'condition_operator_ref_id must reference VALIDATION_OPERATOR';
    END IF;
    IF v_action_type IS DISTINCT FROM 'PARAM_RULE_ACTION' THEN
        RAISE EXCEPTION 'rule_action_ref_id must reference PARAM_RULE_ACTION';
    END IF;
    IF v_field_code <> 'TRIGGER_MODE' THEN
        RAISE EXCEPTION 'unsupported dependency condition field %', v_field_code;
    END IF;
    IF NOT EXISTS (
        SELECT 1
        FROM whale.cfg_task_field_constraint fc
        JOIN whale.ref_code f ON f.ref_code_id=fc.constrained_field_ref_id
        JOIN whale.cfg_value_domain_item di ON di.cfg_value_domain_id=fc.cfg_value_domain_id
        WHERE fc.cfg_protocol_operation_role_id=v_operation_role_id
          AND f.code=v_field_code
          AND di.value_code=NEW.condition_value_code
          AND fc.enabled=TRUE AND fc.valid_to IS NULL
          AND di.enabled=TRUE AND di.valid_to IS NULL
    ) THEN
        RAISE EXCEPTION 'dependency condition value % is not allowed for operation-role % field %', NEW.condition_value_code, v_operation_role_id, v_field_code;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_cfg_task_param_dependency_rule_validate
BEFORE INSERT OR UPDATE ON whale.cfg_task_param_dependency_rule
FOR EACH ROW EXECUTE FUNCTION whale.validate_cfg_task_param_dependency_rule();

CREATE OR REPLACE FUNCTION whale.validate_task_param_text(p_task_param_def_id BIGINT, p_value TEXT)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    v_data_type TEXT;
    v_numeric_min NUMERIC;
    v_numeric_max NUMERIC;
    v_numeric_value NUMERIC;
    v_domain_id BIGINT;
    v_text_pattern TEXT;
BEGIN
    SELECT dt.code, d.numeric_min, d.numeric_max, d.cfg_value_domain_id, d.text_pattern
      INTO v_data_type, v_numeric_min, v_numeric_max, v_domain_id, v_text_pattern
      FROM whale.task_param_def d
      JOIN whale.ref_code dt ON dt.ref_code_id=d.data_type_ref_id
     WHERE d.task_param_def_id=p_task_param_def_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'task_param_def_id % not found', p_task_param_def_id; END IF;

    BEGIN
        IF v_data_type = 'BOOL' THEN
            IF lower(p_value) NOT IN ('true','false') THEN RAISE EXCEPTION 'invalid BOOL'; END IF;
        ELSIF v_data_type = 'INT32' THEN
            PERFORM p_value::INTEGER; v_numeric_value := p_value::NUMERIC;
        ELSIF v_data_type IN ('FLOAT32','FLOAT64','DECIMAL') THEN
            IF lower(p_value) IN ('nan','infinity','+infinity','-infinity','inf','+inf','-inf') THEN
                RAISE EXCEPTION 'non-finite numeric value is not allowed';
            END IF;
            v_numeric_value := p_value::NUMERIC;
        ELSIF v_data_type = 'JSON' THEN
            PERFORM p_value::JSONB;
        ELSIF v_data_type = 'TIMESTAMP' THEN
            PERFORM p_value::TIMESTAMPTZ;
        END IF;
    EXCEPTION WHEN OTHERS THEN
        RAISE EXCEPTION 'task parameter value % does not match data type % for task_param_def_id=%', p_value, v_data_type, p_task_param_def_id;
    END;

    IF v_text_pattern IS NOT NULL AND p_value !~ v_text_pattern THEN
        RAISE EXCEPTION 'task parameter value % does not match pattern % for task_param_def_id=%', p_value, v_text_pattern, p_task_param_def_id;
    END IF;
    IF v_numeric_value IS NOT NULL AND v_numeric_min IS NOT NULL AND v_numeric_value < v_numeric_min THEN
        RAISE EXCEPTION 'task parameter value % is below minimum % for task_param_def_id=%', v_numeric_value, v_numeric_min, p_task_param_def_id;
    END IF;
    IF v_numeric_value IS NOT NULL AND v_numeric_max IS NOT NULL AND v_numeric_value > v_numeric_max THEN
        RAISE EXCEPTION 'task parameter value % is above maximum % for task_param_def_id=%', v_numeric_value, v_numeric_max, p_task_param_def_id;
    END IF;
    IF v_domain_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM whale.cfg_value_domain_item i
        WHERE i.cfg_value_domain_id=v_domain_id AND i.value_code=p_value
          AND i.enabled=TRUE AND i.valid_to IS NULL
    ) THEN
        RAISE EXCEPTION 'task parameter value % is not in cfg_value_domain_id=% for task_param_def_id=%', p_value, v_domain_id, p_task_param_def_id;
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION whale.validate_task_param_def_row()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE v_domain_type BIGINT; v_data_ref_type TEXT; v_unit_ref_type TEXT;
BEGIN
    SELECT ref_type INTO v_data_ref_type FROM whale.ref_code WHERE ref_code_id=NEW.data_type_ref_id;
    IF v_data_ref_type IS DISTINCT FROM 'DATA_TYPE' THEN
        RAISE EXCEPTION 'task_param_def.data_type_ref_id must reference DATA_TYPE';
    END IF;
    IF NEW.engineering_unit_ref_id IS NOT NULL THEN
        SELECT ref_type INTO v_unit_ref_type FROM whale.ref_code WHERE ref_code_id=NEW.engineering_unit_ref_id;
        IF v_unit_ref_type IS DISTINCT FROM 'UNIT' THEN
            RAISE EXCEPTION 'task_param_def.engineering_unit_ref_id must reference UNIT';
        END IF;
    END IF;
    IF NEW.cfg_value_domain_id IS NOT NULL THEN
        SELECT data_type_ref_id INTO v_domain_type FROM whale.cfg_value_domain WHERE cfg_value_domain_id=NEW.cfg_value_domain_id;
        IF v_domain_type IS DISTINCT FROM NEW.data_type_ref_id THEN
            RAISE EXCEPTION 'task_param_def data type must match value domain data type';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_task_param_def_row_validate
BEFORE INSERT OR UPDATE ON whale.task_param_def
FOR EACH ROW EXECUTE FUNCTION whale.validate_task_param_def_row();

CREATE OR REPLACE FUNCTION whale.validate_task_param_def_default()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    IF NEW.default_value IS NOT NULL THEN
        PERFORM whale.validate_task_param_text(NEW.task_param_def_id, NEW.default_value);
    END IF;
    RETURN NEW;
END;
$$;
CREATE CONSTRAINT TRIGGER trg_task_param_def_default_validate
AFTER INSERT OR UPDATE ON whale.task_param_def
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION whale.validate_task_param_def_default();

CREATE OR REPLACE FUNCTION whale.validate_task_param_value_mapping()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE v_task_operation_role BIGINT; v_def_operation_role BIGINT;
BEGIN
    SELECT r.cfg_protocol_operation_role_id
      INTO v_task_operation_role
      FROM whale.task t
      JOIN whale.cfg_protocol_operation_role r
        ON r.protocol_operation_def_id=t.protocol_operation_def_id
       AND r.protocol_role_ref_id=t.protocol_role_ref_id
       AND r.allowed=TRUE AND r.enabled=TRUE AND r.valid_to IS NULL
     WHERE t.task_id=NEW.task_id;
    SELECT cfg_protocol_operation_role_id INTO v_def_operation_role
      FROM whale.task_param_def WHERE task_param_def_id=NEW.task_param_def_id;
    IF v_task_operation_role IS DISTINCT FROM v_def_operation_role THEN
        RAISE EXCEPTION 'task_param_value operation-role mismatch: task_id=% task_param_def_id=%', NEW.task_id, NEW.task_param_def_id;
    END IF;
    PERFORM whale.validate_task_param_text(NEW.task_param_def_id, NEW.param_value);
    RETURN NEW;
END;
$$;
CREATE TRIGGER trg_task_param_value_mapping
BEFORE INSERT OR UPDATE ON whale.task_param_value
FOR EACH ROW EXECUTE FUNCTION whale.validate_task_param_value_mapping();

CREATE OR REPLACE FUNCTION whale.validate_task_integrity(p_task_id BIGINT)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    v_operation_role_id BIGINT; v_conn_protocol BIGINT; v_operation_protocol BIGINT;
    v_point_table_id BIGINT; v_required_usage BIGINT; v_actual_usage BIGINT;
    v_trigger_code TEXT; v_protocol_code TEXT; v_task_role TEXT; v_station_role TEXT;
    v_requires_point_table BOOLEAN; v_view_name TEXT; v_invalid BIGINT;
    v_param_rec RECORD; v_rule_rec RECORD; v_actual TEXT; v_condition BOOLEAN; v_has_value BOOLEAN;
BEGIN
    SELECT r.cfg_protocol_operation_role_id, c.protocol_ref_id, op.protocol_ref_id,
           t.task_point_table_id, r.point_table_usage_ref_id, pt.point_table_usage_ref_id,
           tr.code, p.code, role.code, r.requires_point_table
      INTO v_operation_role_id, v_conn_protocol, v_operation_protocol,
           v_point_table_id, v_required_usage, v_actual_usage,
           v_trigger_code, v_protocol_code, v_task_role, v_requires_point_table
      FROM whale.task t
      JOIN whale.cfg_connection c ON c.cfg_connection_id=t.cfg_connection_id
      JOIN whale.cfg_protocol_operation_def op ON op.cfg_protocol_operation_def_id=t.protocol_operation_def_id
      JOIN whale.cfg_protocol_operation_role r
        ON r.protocol_operation_def_id=t.protocol_operation_def_id
       AND r.protocol_role_ref_id=t.protocol_role_ref_id
       AND r.allowed=TRUE AND r.enabled=TRUE AND r.valid_to IS NULL
      LEFT JOIN whale.task_point_table pt ON pt.task_point_table_id=t.task_point_table_id
      JOIN whale.ref_code tr ON tr.ref_code_id=t.trigger_mode_ref_id
      JOIN whale.ref_code p ON p.ref_code_id=op.protocol_ref_id
      JOIN whale.ref_code role ON role.ref_code_id=t.protocol_role_ref_id
     WHERE t.task_id=p_task_id AND t.valid_to IS NULL;
    IF NOT FOUND THEN
        IF EXISTS (SELECT 1 FROM whale.task WHERE task_id=p_task_id AND valid_to IS NULL) THEN
            RAISE EXCEPTION 'task % has no enabled allowed protocol-operation and protocol-role combination', p_task_id;
        END IF;
        RETURN;
    END IF;

    IF v_conn_protocol IS DISTINCT FROM v_operation_protocol THEN
        RAISE EXCEPTION 'task % connection protocol does not match operation protocol', p_task_id;
    END IF;
    IF v_requires_point_table AND v_point_table_id IS NULL THEN
        RAISE EXCEPTION 'task % requires task_point_table_id', p_task_id;
    END IF;
    IF v_point_table_id IS NOT NULL AND v_actual_usage IS DISTINCT FROM v_required_usage THEN
        RAISE EXCEPTION 'task % task point-table usage does not match operation-role metadata', p_task_id;
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM whale.cfg_task_field_constraint fc
        JOIN whale.ref_code f ON f.ref_code_id=fc.constrained_field_ref_id AND f.ref_type='TASK_CONSTRAINT_FIELD' AND f.code='TRIGGER_MODE'
        JOIN whale.cfg_value_domain_item di ON di.cfg_value_domain_id=fc.cfg_value_domain_id
        WHERE fc.cfg_protocol_operation_role_id=v_operation_role_id AND fc.enabled=TRUE AND fc.valid_to IS NULL
          AND di.value_code=v_trigger_code AND di.enabled=TRUE AND di.valid_to IS NULL
    ) THEN
        RAISE EXCEPTION 'task % trigger mode % is not allowed by operation-role %', p_task_id, v_trigger_code, v_operation_role_id;
    END IF;

    IF v_protocol_code='IEC104' THEN
        SELECT sr.code INTO v_station_role
          FROM whale.task t
          JOIN whale.cfg_iec104_conn ic ON ic.cfg_iec104_conn_id=t.cfg_connection_id
          JOIN whale.ref_code sr ON sr.ref_code_id=ic.station_role_ref_id
         WHERE t.task_id=p_task_id;
        IF (v_station_role='CONTROLLING_STATION' AND v_task_role<>'IEC104_CONTROLLING_STATION') OR
           (v_station_role='CONTROLLED_STATION' AND v_task_role<>'IEC104_CONTROLLED_STATION') THEN
            RAISE EXCEPTION 'task % IEC104 connection role % is incompatible with protocol role %', p_task_id, v_station_role, v_task_role;
        END IF;
    END IF;

    IF v_requires_point_table AND NOT EXISTS (
        SELECT 1 FROM whale.task_point_item i WHERE i.task_point_table_id=v_point_table_id AND i.enabled=TRUE AND i.valid_to IS NULL
    ) THEN
        RAISE EXCEPTION 'task % requires a non-empty task point table', p_task_id;
    END IF;
    IF v_point_table_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM whale.task_point_item i
        WHERE i.task_point_table_id=v_point_table_id AND i.enabled=TRUE AND i.valid_to IS NULL
          AND i.protocol_ref_id<>v_operation_protocol
    ) THEN
        RAISE EXCEPTION 'task % contains task points from another protocol', p_task_id;
    END IF;

    IF v_point_table_id IS NOT NULL THEN
        SELECT count(*) INTO v_invalid
          FROM whale.task_point_item i JOIN whale.ref_code pr ON pr.ref_code_id=i.point_role_ref_id
         WHERE i.task_point_table_id=v_point_table_id AND i.enabled=TRUE AND i.valid_to IS NULL
           AND NOT EXISTS (
             SELECT 1 FROM whale.cfg_task_field_constraint fc
             JOIN whale.ref_code f ON f.ref_code_id=fc.constrained_field_ref_id AND f.code='POINT_ROLE'
             JOIN whale.cfg_value_domain_item di ON di.cfg_value_domain_id=fc.cfg_value_domain_id
             WHERE fc.cfg_protocol_operation_role_id=v_operation_role_id AND fc.enabled=TRUE AND fc.valid_to IS NULL
               AND di.value_code=pr.code AND di.enabled=TRUE AND di.valid_to IS NULL
           );
        IF v_invalid>0 THEN RAISE EXCEPTION 'task % contains disallowed point roles', p_task_id; END IF;

        SELECT count(*) INTO v_invalid
          FROM whale.task_point_item i JOIN whale.ref_code sm ON sm.ref_code_id=i.sample_mode_ref_id
         WHERE i.task_point_table_id=v_point_table_id AND i.enabled=TRUE AND i.valid_to IS NULL
           AND NOT EXISTS (
             SELECT 1 FROM whale.cfg_task_field_constraint fc
             JOIN whale.ref_code f ON f.ref_code_id=fc.constrained_field_ref_id AND f.code='SAMPLE_MODE'
             JOIN whale.cfg_value_domain_item di ON di.cfg_value_domain_id=fc.cfg_value_domain_id
             WHERE fc.cfg_protocol_operation_role_id=v_operation_role_id AND fc.enabled=TRUE AND fc.valid_to IS NULL
               AND di.value_code=sm.code AND di.enabled=TRUE AND di.valid_to IS NULL
           );
        IF v_invalid>0 THEN RAISE EXCEPTION 'task % contains disallowed sample modes', p_task_id; END IF;
    END IF;

    IF v_point_table_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM whale.cfg_task_field_constraint fc JOIN whale.ref_code f ON f.ref_code_id=fc.constrained_field_ref_id
        WHERE fc.cfg_protocol_operation_role_id=v_operation_role_id AND f.code='PROTOCOL_TYPE_ID' AND fc.enabled=TRUE AND fc.valid_to IS NULL
    ) THEN
        SELECT registry.table_name INTO v_view_name
          FROM whale.cfg_protocol_table_registry AS registry
          JOIN whale.ref_code AS registry_role ON registry_role.ref_code_id=registry.table_role_ref_id
         WHERE registry.protocol_ref_id=v_operation_protocol
           AND registry_role.code='POINT_ITEM_VIEW'
           AND registry.enabled=TRUE AND registry.valid_to IS NULL
         ORDER BY registry.cfg_protocol_table_registry_id DESC LIMIT 1;
        EXECUTE format($q$
          SELECT count(*) FROM whale.task_point_item ti
          JOIN whale.%I pi ON pi.point_item_id=ti.protocol_point_item_id
          WHERE ti.task_point_table_id=$1 AND ti.enabled=TRUE AND ti.valid_to IS NULL
            AND NOT EXISTS (
              SELECT 1 FROM whale.cfg_task_field_constraint fc
              JOIN whale.ref_code f ON f.ref_code_id=fc.constrained_field_ref_id AND f.code='PROTOCOL_TYPE_ID'
              JOIN whale.cfg_value_domain_item di ON di.cfg_value_domain_id=fc.cfg_value_domain_id
              WHERE fc.cfg_protocol_operation_role_id=$2 AND fc.enabled=TRUE AND fc.valid_to IS NULL
                AND di.value_code=pi.type_id AND di.enabled=TRUE AND di.valid_to IS NULL
            )$q$, v_view_name)
          INTO v_invalid USING v_point_table_id, v_operation_role_id;
        IF v_invalid>0 THEN RAISE EXCEPTION 'task % contains disallowed protocol Type IDs', p_task_id; END IF;
    END IF;

    FOR v_param_rec IN
        SELECT d.task_param_def_id, d.param_identifier, d.required, d.default_value
        FROM whale.task_param_def d
        WHERE d.cfg_protocol_operation_role_id=v_operation_role_id AND d.enabled=TRUE AND d.valid_to IS NULL
    LOOP
        SELECT EXISTS (SELECT 1 FROM whale.task_param_value v WHERE v.task_id=p_task_id AND v.task_param_def_id=v_param_rec.task_param_def_id AND v.enabled=TRUE AND v.valid_to IS NULL)
          INTO v_has_value;
        IF v_param_rec.required AND NOT v_has_value AND v_param_rec.default_value IS NULL THEN
            RAISE EXCEPTION 'task % missing required parameter %', p_task_id, v_param_rec.param_identifier;
        END IF;
    END LOOP;

    FOR v_rule_rec IN
        SELECT rule.*, f.code AS field_code, op.code AS operator_code, act.code AS action_code,
               d.default_value, d.param_identifier
        FROM whale.cfg_task_param_dependency_rule rule
        JOIN whale.task_param_def d ON d.task_param_def_id=rule.target_task_param_def_id
        JOIN whale.ref_code f ON f.ref_code_id=rule.condition_field_ref_id
        JOIN whale.ref_code op ON op.ref_code_id=rule.condition_operator_ref_id
        JOIN whale.ref_code act ON act.ref_code_id=rule.rule_action_ref_id
        WHERE d.cfg_protocol_operation_role_id=v_operation_role_id AND rule.enabled=TRUE AND rule.valid_to IS NULL
    LOOP
        IF v_rule_rec.field_code='TRIGGER_MODE' THEN v_actual:=v_trigger_code;
        ELSE RAISE EXCEPTION 'unsupported task dependency field %', v_rule_rec.field_code; END IF;
        v_condition := CASE v_rule_rec.operator_code WHEN 'EQUALS' THEN v_actual=v_rule_rec.condition_value_code WHEN 'NOT_EQUALS' THEN v_actual<>v_rule_rec.condition_value_code ELSE FALSE END;
        IF v_condition THEN
            SELECT EXISTS (SELECT 1 FROM whale.task_param_value v WHERE v.task_id=p_task_id AND v.task_param_def_id=v_rule_rec.target_task_param_def_id AND v.enabled=TRUE AND v.valid_to IS NULL)
              INTO v_has_value;
            IF v_rule_rec.action_code='REQUIRED' AND NOT v_has_value AND v_rule_rec.default_value IS NULL THEN
                RAISE EXCEPTION 'task % parameter % is required by dependency rule', p_task_id, v_rule_rec.param_identifier;
            ELSIF v_rule_rec.action_code='FORBIDDEN' AND v_has_value THEN
                RAISE EXCEPTION 'task % parameter % is forbidden by dependency rule', p_task_id, v_rule_rec.param_identifier;
            END IF;
        END IF;
    END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION whale.trg_validate_task_integrity()
RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN PERFORM whale.validate_task_integrity(NEW.task_id); RETURN NEW; END;
$$;
CREATE CONSTRAINT TRIGGER trg_task_integrity
AFTER INSERT OR UPDATE ON whale.task
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION whale.trg_validate_task_integrity();

CREATE OR REPLACE FUNCTION whale.trg_validate_task_from_param()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_task_id BIGINT;
BEGIN
  v_task_id := CASE WHEN TG_OP='DELETE' THEN OLD.task_id ELSE NEW.task_id END;
  PERFORM whale.validate_task_integrity(v_task_id);
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;
CREATE CONSTRAINT TRIGGER trg_task_from_param
AFTER INSERT OR UPDATE OR DELETE ON whale.task_param_value
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION whale.trg_validate_task_from_param();

CREATE OR REPLACE FUNCTION whale.trg_validate_task_from_item()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r RECORD; v_old_table BIGINT; v_new_table BIGINT;
BEGIN
  v_old_table := CASE WHEN TG_OP IN ('UPDATE','DELETE') THEN OLD.task_point_table_id ELSE NULL END;
  v_new_table := CASE WHEN TG_OP IN ('INSERT','UPDATE') THEN NEW.task_point_table_id ELSE NULL END;
  FOR r IN
      SELECT DISTINCT task_id
      FROM whale.task
      WHERE task_point_table_id IN (v_old_table,v_new_table)
        AND valid_to IS NULL
  LOOP PERFORM whale.validate_task_integrity(r.task_id); END LOOP;
  IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END;
$$;
CREATE CONSTRAINT TRIGGER trg_task_from_item
AFTER INSERT OR UPDATE OR DELETE ON whale.task_point_item
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION whale.trg_validate_task_from_item();

CREATE OR REPLACE FUNCTION whale.trg_validate_task_from_point_table()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT task_id FROM whale.task WHERE task_point_table_id=NEW.task_point_table_id AND valid_to IS NULL
  LOOP PERFORM whale.validate_task_integrity(r.task_id); END LOOP;
  RETURN NEW;
END;
$$;
CREATE CONSTRAINT TRIGGER trg_task_from_point_table
AFTER UPDATE ON whale.task_point_table
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION whale.trg_validate_task_from_point_table();

CREATE OR REPLACE FUNCTION whale.protect_task_constraint_metadata_in_use()
RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_operation_role_id BIGINT;
BEGIN
  IF TG_TABLE_NAME='task_param_def' THEN
      v_operation_role_id := OLD.cfg_protocol_operation_role_id;
  ELSIF TG_TABLE_NAME='cfg_task_param_dependency_rule' THEN
      SELECT cfg_protocol_operation_role_id INTO v_operation_role_id
      FROM whale.task_param_def WHERE task_param_def_id=OLD.target_task_param_def_id;
  ELSE
      RETURN OLD;
  END IF;
  IF EXISTS (
      SELECT 1 FROM whale.task t
      JOIN whale.cfg_protocol_operation_role r
        ON r.protocol_operation_def_id=t.protocol_operation_def_id
       AND r.protocol_role_ref_id=t.protocol_role_ref_id
      WHERE r.cfg_protocol_operation_role_id=v_operation_role_id
        AND t.valid_to IS NULL
  ) THEN
      RAISE EXCEPTION 'cannot delete task constraint metadata for operation-role % while active tasks exist', v_operation_role_id;
  END IF;
  RETURN OLD;
END;
$$;
CREATE TRIGGER trg_protect_task_param_def_delete
BEFORE DELETE ON whale.task_param_def
FOR EACH ROW EXECUTE FUNCTION whale.protect_task_constraint_metadata_in_use();
CREATE TRIGGER trg_protect_task_dependency_rule_delete
BEFORE DELETE ON whale.cfg_task_param_dependency_rule
FOR EACH ROW EXECUTE FUNCTION whale.protect_task_constraint_metadata_in_use();


CREATE TABLE whale.task_run (
    task_run_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id BIGINT NOT NULL REFERENCES whale.task(task_id),
    run_identifier TEXT NOT NULL,
    run_scope_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    run_status_ref_id BIGINT NOT NULL REFERENCES whale.ref_code(ref_code_id),
    started_at TIMESTAMPTZ NOT NULL,
    finished_at TIMESTAMPTZ,
    success_count INTEGER NOT NULL DEFAULT 0,
    failure_count INTEGER NOT NULL DEFAULT 0,
    message_zh TEXT NOT NULL,
    message_en TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by TEXT NOT NULL DEFAULT 'system',
    UNIQUE(run_identifier)
);
COMMENT ON TABLE whale.task_run IS '【过程数据】任务运行记录表。记录任务的一次运行、会话、命令、发布或响应服务窗口。';
