COMMENT ON COLUMN whale.task_run.run_identifier IS '运行记录业务稳定标识。';
COMMENT ON COLUMN whale.task_run.run_scope_ref_id IS '运行记录粒度，取值来自 TASK_RUN_SCOPE。';
COMMENT ON COLUMN whale.task_run.run_status_ref_id IS '运行状态，取值来自 TASK_RUN_STATUS。';
COMMENT ON COLUMN whale.task_run.started_at IS '运行开始时间。';
COMMENT ON COLUMN whale.task_run.finished_at IS '运行结束时间。';
COMMENT ON COLUMN whale.task_run.success_count IS '成功数量。';
COMMENT ON COLUMN whale.task_run.failure_count IS '失败数量。';
COMMENT ON COLUMN whale.task_run.message_zh IS '中文运行说明。';
COMMENT ON COLUMN whale.task_run.message_en IS '英文运行说明。';
COMMENT ON COLUMN whale.task_run.created_at IS '记录创建时间。';
COMMENT ON COLUMN whale.task_run.created_by IS '记录创建人。';


