COMMENT ON COLUMN whale.cfg_iec104_point_item.quality_descriptor_enabled IS '是否包含 IEC104 质量描述符；用于驱动解析无效、非当前、替代、闭锁等质量位。';
COMMENT ON COLUMN whale.cfg_iec61850_mms_point_item.logical_device IS 'IEC 61850 逻辑设备名，用于从 object_reference 中拆分出驱动寻址层级。';
