COMMENT ON COLUMN whale.cfg_iec61850_mms_point_item.data_attribute IS 'IEC 61850 数据属性名，例如 mag.f、stVal、q、t。';
COMMENT ON COLUMN whale.cfg_iec61850_goose_point_item.cdc_ref_id IS 'GOOSE 数据成员的 CDC，取值来自 ref_code.ref_type=IEC61850_CDC。';
COMMENT ON COLUMN whale.cfg_iec61850_goose_point_item.btype_ref_id IS 'GOOSE 数据成员基础类型，取值来自 ref_code.ref_type=PROTOCOL_DATA_TYPE。';
COMMENT ON COLUMN whale.cfg_iec61850_sv_point_item.phase_ref_id IS '采样通道相别，取值来自 ref_code.ref_type=PHASE。';
COMMENT ON COLUMN whale.cfg_iec61850_sv_point_item.quantity_ref_id IS '采样量类型，取值来自 ref_code.ref_type=SV_QUANTITY。';
COMMENT ON COLUMN whale.cfg_iec61850_sv_point_item.cdc_ref_id IS 'SV 数据成员 CDC，取值来自 ref_code.ref_type=IEC61850_CDC。';
COMMENT ON COLUMN whale.cfg_iec61850_sv_point_item.btype_ref_id IS 'SV 数据成员基础类型，取值来自 ref_code.ref_type=PROTOCOL_DATA_TYPE。';
