CREATE OR REPLACE VIEW whale.vw_employee_full AS
SELECT e.emp_employee_id AS employee_id, e.power_plant_id, e.name_zh AS employee_name,
       role.role_identifier AS role_name, perm.permission_identifier AS permission_name, e.on_duty
FROM whale.emp_employee e
JOIN whale.sec_employee_role er ON er.employee_id = e.emp_employee_id
JOIN whale.sec_role role ON role.sec_role_id = er.role_id
JOIN whale.sec_role_permission rp ON rp.role_id = role.sec_role_id
JOIN whale.sec_permission perm ON perm.sec_permission_id = rp.permission_id
WHERE e.in_service = TRUE AND e.enabled = TRUE AND e.valid_to IS NULL
ORDER BY e.power_plant_id, e.emp_employee_id, role.role_identifier, perm.permission_identifier;
COMMENT ON VIEW whale.vw_employee_full IS '【主数据】在职员工权限视图。只展示在职员工、角色和权限。';
COMMENT ON COLUMN whale.vw_employee_full.employee_id IS '员工主键，来自 emp_employee.emp_employee_id。';
COMMENT ON COLUMN whale.vw_employee_full.power_plant_id IS '所属风光储电场主键，来自 emp_employee.power_plant_id。';
COMMENT ON COLUMN whale.vw_employee_full.employee_name IS '员工中文姓名，来自 emp_employee.name_zh。';
COMMENT ON COLUMN whale.vw_employee_full.role_name IS '系统角色标识，来自 sec_role.role_identifier。';
COMMENT ON COLUMN whale.vw_employee_full.permission_name IS '权限标识，来自 sec_permission.permission_identifier。';
COMMENT ON COLUMN whale.vw_employee_full.on_duty IS '是否当班，来自 emp_employee.on_duty；不同于 in_service。';


CREATE OR REPLACE VIEW whale.vw_asset_full AS
SELECT a.ast_asset_id AS asset_id, a.asset_identifier, a.name_zh AS asset_name,
       at.code AS asset_type_code, at.name_zh AS asset_type_name,
       m.model_identifier AS asset_model, mf.name_zh AS manufacturer_name,
       a.production_date, a.installation_date, a.commissioning_date
FROM whale.ast_asset a
JOIN whale.ref_code at ON at.ref_code_id = a.asset_type_ref_id
JOIN whale.ast_asset_model m ON m.ast_asset_model_id = a.model_id
JOIN whale.ast_manufacturer mf ON mf.ast_manufacturer_id = m.manufacturer_id
JOIN whale.ref_code lifecycle ON lifecycle.ref_code_id = a.asset_lifecycle_status_ref_id
WHERE a.enabled = TRUE AND a.valid_to IS NULL AND lifecycle.code = 'IN_OPERATION'
ORDER BY at.sort_order, a.asset_identifier;
COMMENT ON VIEW whale.vw_asset_full IS '【主数据】使用中资产视图。只展示当前使用中的真实资产核心台账字段。';
COMMENT ON COLUMN whale.vw_asset_full.asset_id IS '资产主键，来自 ast_asset.ast_asset_id。';
COMMENT ON COLUMN whale.vw_asset_full.asset_identifier IS '场站或系统内部分配的资产唯一标识，来自 ast_asset.asset_identifier。';
COMMENT ON COLUMN whale.vw_asset_full.asset_name IS '资产中文名称，来自 ast_asset.name_zh。';
COMMENT ON COLUMN whale.vw_asset_full.asset_type_code IS '资产类型 code，来自 ref_code.ref_type=ASSET_TYPE。';
COMMENT ON COLUMN whale.vw_asset_full.asset_type_name IS '资产类型中文名，来自 ref_code.name_zh。';
COMMENT ON COLUMN whale.vw_asset_full.asset_model IS '资产型号标识，来自 ast_asset_model.model_identifier。';
COMMENT ON COLUMN whale.vw_asset_full.manufacturer_name IS '生产厂家中文名，来自 ast_manufacturer.name_zh。';
COMMENT ON COLUMN whale.vw_asset_full.production_date IS '生产日期，来自 ast_asset.production_date。';
COMMENT ON COLUMN whale.vw_asset_full.installation_date IS '现场安装日期，来自 ast_asset.installation_date。';
COMMENT ON COLUMN whale.vw_asset_full.commissioning_date IS '启用或投运日期，来自 ast_asset.commissioning_date。';


CREATE OR REPLACE VIEW whale.vw_geo_location AS
SELECT
    a.ast_asset_id AS asset_id,
    a.asset_identifier,
    at.code AS asset_type_code,
    at.name_zh AS asset_type_name,
    g.coordinate_system,
    g.longitude,
    g.latitude,
    g.altitude_m,
    g.coordinate_x,
    g.coordinate_y,
    g.height_m,
    g.rotation_x,
    g.rotation_y,
    g.rotation_z,
    g.scale_x,
    g.scale_y,
    g.scale_z,
    g.model_file_name
FROM whale.geo_location g
JOIN whale.ast_asset a ON a.ast_asset_id = g.asset_id
JOIN whale.ref_code at ON at.ref_code_id = a.asset_type_ref_id
JOIN whale.ref_code lifecycle ON lifecycle.ref_code_id = a.asset_lifecycle_status_ref_id
WHERE g.enabled = TRUE AND g.valid_to IS NULL
  AND a.enabled = TRUE AND a.valid_to IS NULL
  AND lifecycle.code = 'IN_OPERATION'
ORDER BY at.sort_order, a.asset_identifier;
COMMENT ON VIEW whale.vw_geo_location IS '【主数据】资产三维位置视图。只展示最新版本、需要在三维图显示的大型真实资产位置、模型、旋转和缩放参数。';
COMMENT ON COLUMN whale.vw_geo_location.asset_id IS '资产主键，来自 geo_location.asset_id 关联 ast_asset.ast_asset_id。';
COMMENT ON COLUMN whale.vw_geo_location.asset_identifier IS '资产业务标识，来自 ast_asset.asset_identifier。';
COMMENT ON COLUMN whale.vw_geo_location.asset_type_code IS '资产类型 code，来自 ref_code.ref_type=ASSET_TYPE。';
COMMENT ON COLUMN whale.vw_geo_location.asset_type_name IS '资产类型中文名，来自 ref_code.name_zh。';
COMMENT ON COLUMN whale.vw_geo_location.coordinate_system IS '坐标系，来自 geo_location.coordinate_system。';
COMMENT ON COLUMN whale.vw_geo_location.longitude IS '经度，来自 geo_location.longitude。';
COMMENT ON COLUMN whale.vw_geo_location.latitude IS '纬度，来自 geo_location.latitude。';
COMMENT ON COLUMN whale.vw_geo_location.altitude_m IS '海拔高程，单位米，来自 geo_location.altitude_m。';
COMMENT ON COLUMN whale.vw_geo_location.coordinate_x IS '场站平面或投影坐标 X，来自 geo_location.coordinate_x。';
COMMENT ON COLUMN whale.vw_geo_location.coordinate_y IS '场站平面或投影坐标 Y，来自 geo_location.coordinate_y。';
COMMENT ON COLUMN whale.vw_geo_location.height_m IS '设备或模型高度，单位米，来自 geo_location.height_m。';
COMMENT ON COLUMN whale.vw_geo_location.rotation_x IS '三维模型绕 X 轴旋转角，来自 geo_location.rotation_x。';
COMMENT ON COLUMN whale.vw_geo_location.rotation_y IS '三维模型绕 Y 轴旋转角，来自 geo_location.rotation_y。';
COMMENT ON COLUMN whale.vw_geo_location.rotation_z IS '三维模型绕 Z 轴旋转角，来自 geo_location.rotation_z。';
COMMENT ON COLUMN whale.vw_geo_location.scale_x IS '三维模型 X 方向缩放比例，来自 geo_location.scale_x。';
COMMENT ON COLUMN whale.vw_geo_location.scale_y IS '三维模型 Y 方向缩放比例，来自 geo_location.scale_y。';
COMMENT ON COLUMN whale.vw_geo_location.scale_z IS '三维模型 Z 方向缩放比例，来自 geo_location.scale_z。';
COMMENT ON COLUMN whale.vw_geo_location.model_file_name IS '三维模型文件名，来自 geo_location.model_file_name。';


CREATE OR REPLACE VIEW whale.vw_asset_position_full AS
SELECT * FROM whale.vw_geo_location;
COMMENT ON VIEW whale.vw_asset_position_full IS '【主数据】资产三维位置兼容视图。字段与 vw_geo_location 相同，保留用于兼容旧命名。';
COMMENT ON COLUMN whale.vw_asset_position_full.asset_id IS '兼容字段，与 vw_geo_location.asset_id 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.asset_identifier IS '兼容字段，与 vw_geo_location.asset_identifier 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.asset_type_code IS '兼容字段，与 vw_geo_location.asset_type_code 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.asset_type_name IS '兼容字段，与 vw_geo_location.asset_type_name 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.coordinate_system IS '兼容字段，与 vw_geo_location.coordinate_system 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.longitude IS '兼容字段，与 vw_geo_location.longitude 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.latitude IS '兼容字段，与 vw_geo_location.latitude 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.altitude_m IS '兼容字段，与 vw_geo_location.altitude_m 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.coordinate_x IS '兼容字段，与 vw_geo_location.coordinate_x 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.coordinate_y IS '兼容字段，与 vw_geo_location.coordinate_y 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.height_m IS '兼容字段，与 vw_geo_location.height_m 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.rotation_x IS '兼容字段，与 vw_geo_location.rotation_x 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.rotation_y IS '兼容字段，与 vw_geo_location.rotation_y 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.rotation_z IS '兼容字段，与 vw_geo_location.rotation_z 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.scale_x IS '兼容字段，与 vw_geo_location.scale_x 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.scale_y IS '兼容字段，与 vw_geo_location.scale_y 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.scale_z IS '兼容字段，与 vw_geo_location.scale_z 含义一致。';
COMMENT ON COLUMN whale.vw_asset_position_full.model_file_name IS '兼容字段，与 vw_geo_location.model_file_name 含义一致。';


CREATE OR REPLACE VIEW whale.vw_connection_object_full AS
SELECT
    c.cfg_connection_id AS connection_id,
    a.ast_asset_id AS asset_id,
    a.asset_identifier,
    a.name_zh AS asset_name,
    at.code AS asset_type_code,
    at.name_zh AS asset_type_name,
    p.code AS protocol,
    i104_role.code AS station_role,
    CASE p.code
        WHEN 'MODBUS' THEN jsonb_build_object('host', mb.host::text, 'port', mb.port, 'slave_id', mb.slave_id, 'transport', mb_transport.code, 'timeout_ms', mb.timeout_ms)
        WHEN 'OPCUA' THEN jsonb_build_object('endpoint_url', opc.endpoint_url, 'security_policy', opc_sec_policy.code, 'security_mode', opc_sec_mode.code, 'username', opc.username, 'timeout_ms', opc.timeout_ms)
        WHEN 'ADS' THEN jsonb_build_object('host', ads.host::text, 'ams_net_id', ads.ams_net_id, 'ams_port', ads.ams_port, 'route_name', ads.route_name, 'timeout_ms', ads.timeout_ms)
        WHEN 'IEC101' THEN jsonb_build_object('serial_port', i101.serial_port, 'baud_rate', i101.baud_rate, 'link_address', i101.link_address, 'common_address', i101.common_address, 'balanced_mode', i101.balanced_mode, 'timeout_ms', i101.timeout_ms)
        WHEN 'IEC104' THEN jsonb_build_object(
            'station_role', i104_role.code,
            'host', i104.host::text,
            'port', i104.port,
            'remote_host', CASE WHEN i104_role.code='CONTROLLING_STATION' THEN i104.host::text ELSE NULL END,
            'remote_port', CASE WHEN i104_role.code='CONTROLLING_STATION' THEN i104.port ELSE NULL END,
            'listen_host', CASE WHEN i104_role.code='CONTROLLED_STATION' THEN i104.host::text ELSE NULL END,
            'listen_port', CASE WHEN i104_role.code='CONTROLLED_STATION' THEN i104.port ELSE NULL END,
            'point_table_id', i104.cfg_iec104_point_table_id,
            'point_table_identifier', i104_pt.point_table_identifier,
            'common_address', i104.common_address,
            't0_ms', i104.t0_ms, 't1_ms', i104.t1_ms, 't2_ms', i104.t2_ms, 't3_ms', i104.t3_ms,
            'k_value', i104.k_value, 'w_value', i104.w_value, 'timeout_ms', i104.timeout_ms,
            'reconnect_enabled', i104.reconnect_enabled, 'reconnect_interval_ms', i104.reconnect_interval_ms,
            'max_client_count', i104.max_client_count)
        WHEN 'IEC61850_MMS' THEN jsonb_build_object('host', mms.host::text, 'port', mms.port, 'ied_name', mms.ied_name, 'access_point', mms.access_point, 'timeout_ms', mms.timeout_ms)
        WHEN 'IEC61850_GOOSE' THEN jsonb_build_object('network_interface', goose.network_interface, 'app_id', goose.appid, 'multicast_mac', goose.multicast_mac, 'vlan_id', goose.vlan_id, 'timeout_ms', goose.timeout_ms)
        WHEN 'IEC61850_SV' THEN jsonb_build_object('network_interface', sv.network_interface, 'sv_id', sv.sv_id, 'app_id', sv.appid, 'sample_rate_hz', sv.sample_rate_hz, 'vlan_id', sv.vlan_id, 'timeout_ms', sv.timeout_ms)
        WHEN 'MQTT' THEN jsonb_build_object('broker_url', mqtt.broker_url, 'client_id', mqtt.client_id, 'username', mqtt.username, 'qos', mqtt.qos, 'clean_session', mqtt.clean_session, 'timeout_ms', mqtt.timeout_ms)
        WHEN 'HTTP_REST' THEN jsonb_build_object('base_url', http.base_url, 'host_address', http.host_address::text, 'port', http.port, 'auth_type', http_auth.code, 'username', http.username, 'timeout_ms', http.timeout_ms)
    END AS connection_params_json,
    point_view.table_name AS point_item_view_name
FROM whale.cfg_connection c
JOIN whale.ast_asset a ON a.ast_asset_id=c.asset_id
JOIN whale.ref_code at ON at.ref_code_id=a.asset_type_ref_id
JOIN whale.ref_code p ON p.ref_code_id=c.protocol_ref_id
LEFT JOIN whale.cfg_protocol_table_registry point_view ON point_view.protocol_ref_id=p.ref_code_id
 AND point_view.table_role_ref_id=(SELECT ref_code_id FROM whale.ref_code WHERE ref_type='PROTOCOL_TABLE_ROLE' AND code='POINT_ITEM_VIEW' AND enabled ORDER BY ref_code_id DESC LIMIT 1)
 AND point_view.enabled AND point_view.valid_to IS NULL
LEFT JOIN whale.cfg_modbus_conn mb ON mb.cfg_modbus_conn_id=c.cfg_connection_id
LEFT JOIN whale.ref_code mb_transport ON mb_transport.ref_code_id=mb.transport_ref_id
LEFT JOIN whale.cfg_opcua_conn opc ON opc.cfg_opcua_conn_id=c.cfg_connection_id
LEFT JOIN whale.ref_code opc_sec_policy ON opc_sec_policy.ref_code_id=opc.security_policy_ref_id
LEFT JOIN whale.ref_code opc_sec_mode ON opc_sec_mode.ref_code_id=opc.security_mode_ref_id
LEFT JOIN whale.cfg_ads_conn ads ON ads.cfg_ads_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_iec101_conn i101 ON i101.cfg_iec101_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_iec104_conn i104 ON i104.cfg_iec104_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_iec104_point_table i104_pt ON i104_pt.cfg_iec104_point_table_id=i104.cfg_iec104_point_table_id
LEFT JOIN whale.ref_code i104_role ON i104_role.ref_code_id=i104.station_role_ref_id
LEFT JOIN whale.cfg_iec61850_mms_conn mms ON mms.cfg_iec61850_mms_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_iec61850_goose_conn goose ON goose.cfg_iec61850_goose_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_iec61850_sv_conn sv ON sv.cfg_iec61850_sv_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_mqtt_conn mqtt ON mqtt.cfg_mqtt_conn_id=c.cfg_connection_id
LEFT JOIN whale.cfg_http_rest_conn http ON http.cfg_http_rest_conn_id=c.cfg_connection_id
LEFT JOIN whale.ref_code http_auth ON http_auth.ref_code_id=http.auth_type_ref_id
ORDER BY p.sort_order, a.asset_identifier, c.cfg_connection_id;
COMMENT ON VIEW whale.vw_connection_object_full IS '【配置数据】统一连接执行视图。全部协议连接参数集中在 connection_params_json；不再提供协议专用连接视图名。';
COMMENT ON COLUMN whale.vw_connection_object_full.connection_id IS '通用连接主键。';
COMMENT ON COLUMN whale.vw_connection_object_full.asset_id IS '连接对象资产主键。';
COMMENT ON COLUMN whale.vw_connection_object_full.asset_identifier IS '连接对象资产业务标识。';
COMMENT ON COLUMN whale.vw_connection_object_full.asset_name IS '连接对象资产中文名称。';
COMMENT ON COLUMN whale.vw_connection_object_full.asset_type_code IS '资产类型 code。';
COMMENT ON COLUMN whale.vw_connection_object_full.asset_type_name IS '资产类型中文名。';
COMMENT ON COLUMN whale.vw_connection_object_full.protocol IS '协议 code。';
COMMENT ON COLUMN whale.vw_connection_object_full.station_role IS 'IEC104 站端角色；其他协议为空。';
COMMENT ON COLUMN whale.vw_connection_object_full.connection_params_json IS '协议连接参数 JSON；IEC104 仅包含连接级参数，协议行为参数由 vw_task_full.task_params_json 提供。';
COMMENT ON COLUMN whale.vw_connection_object_full.point_item_view_name IS '统一协议点位执行视图名。';

CREATE OR REPLACE VIEW whale.vw_task_param_def_full AS
WITH domain_values AS (
 SELECT i.cfg_value_domain_id,
        jsonb_agg(jsonb_build_object('value',i.value_code,'name_zh',i.name_zh,'name_en',i.name_en) ORDER BY i.sort_order,i.value_code) AS allowed_values_json
 FROM whale.cfg_value_domain_item i
 WHERE i.enabled AND i.valid_to IS NULL
 GROUP BY i.cfg_value_domain_id
)
SELECT d.task_param_def_id, d.cfg_protocol_operation_role_id,
       p.code AS protocol, op.operation_identifier, op.native_operation_code,
       role.code AS protocol_role,
       d.param_identifier,d.name_zh,d.name_en,dt.code AS data_type,unit.code AS unit_code,
       domain.domain_identifier AS value_domain_identifier,d.required,d.default_value,d.numeric_min,d.numeric_max,d.text_pattern,
       domain_values.allowed_values_json,d.description_zh,d.description_en
FROM whale.task_param_def d
JOIN whale.cfg_protocol_operation_role r ON r.cfg_protocol_operation_role_id=d.cfg_protocol_operation_role_id
JOIN whale.cfg_protocol_operation_def op ON op.cfg_protocol_operation_def_id=r.protocol_operation_def_id
JOIN whale.ref_code p ON p.ref_code_id=op.protocol_ref_id
JOIN whale.ref_code role ON role.ref_code_id=r.protocol_role_ref_id
JOIN whale.ref_code dt ON dt.ref_code_id=d.data_type_ref_id
LEFT JOIN whale.ref_code unit ON unit.ref_code_id=d.engineering_unit_ref_id
LEFT JOIN whale.cfg_value_domain domain ON domain.cfg_value_domain_id=d.cfg_value_domain_id
LEFT JOIN domain_values ON domain_values.cfg_value_domain_id=d.cfg_value_domain_id
WHERE d.enabled AND d.valid_to IS NULL
ORDER BY p.sort_order, op.operation_identifier, role.code, d.param_identifier;
COMMENT ON VIEW whale.vw_task_param_def_full IS '【元数据】任务参数定义视图。按协议原生操作和协议角色输出参数类型、范围、取值域和默认值。';
COMMENT ON COLUMN whale.vw_task_param_def_full.task_param_def_id IS '任务参数定义主键。';
COMMENT ON COLUMN whale.vw_task_param_def_full.cfg_protocol_operation_role_id IS '协议原生操作—协议角色组合主键。';
COMMENT ON COLUMN whale.vw_task_param_def_full.protocol IS '协议 code。';
COMMENT ON COLUMN whale.vw_task_param_def_full.operation_identifier IS '协议原生操作稳定标识。';
COMMENT ON COLUMN whale.vw_task_param_def_full.native_operation_code IS '协议原生操作码或工程操作码。';
COMMENT ON COLUMN whale.vw_task_param_def_full.protocol_role IS '按协议规范命名的角色。';
COMMENT ON COLUMN whale.vw_task_param_def_full.param_identifier IS '参数业务稳定标识。';
COMMENT ON COLUMN whale.vw_task_param_def_full.name_zh IS '参数中文名。';
COMMENT ON COLUMN whale.vw_task_param_def_full.name_en IS '参数英文名。';
COMMENT ON COLUMN whale.vw_task_param_def_full.data_type IS '参数数据类型。';
COMMENT ON COLUMN whale.vw_task_param_def_full.unit_code IS '参数工程单位。';
COMMENT ON COLUMN whale.vw_task_param_def_full.value_domain_identifier IS '集中取值域标识。';
COMMENT ON COLUMN whale.vw_task_param_def_full.required IS '是否无条件必填。';
COMMENT ON COLUMN whale.vw_task_param_def_full.default_value IS '参数默认值。';
COMMENT ON COLUMN whale.vw_task_param_def_full.numeric_min IS '数值下限。';
COMMENT ON COLUMN whale.vw_task_param_def_full.numeric_max IS '数值上限。';
COMMENT ON COLUMN whale.vw_task_param_def_full.text_pattern IS '字符串格式正则。';
COMMENT ON COLUMN whale.vw_task_param_def_full.allowed_values_json IS '允许值集合。';
COMMENT ON COLUMN whale.vw_task_param_def_full.description_zh IS '参数中文说明。';
COMMENT ON COLUMN whale.vw_task_param_def_full.description_en IS '参数英文说明。';

CREATE OR REPLACE VIEW whale.vw_task_full AS
WITH param_agg AS (
 SELECT t.task_id,
        jsonb_strip_nulls(
          jsonb_build_object(
            'trigger_mode', trigger.code,
            'timeout_ms', t.timeout_ms,
            'retry_count', t.retry_count
          ) || COALESCE(
            jsonb_object_agg(d.param_identifier, COALESCE(v.param_value,d.default_value) ORDER BY d.param_identifier)
              FILTER (WHERE COALESCE(v.param_value,d.default_value) IS NOT NULL),
            '{}'::jsonb
          )
        ) AS task_params_json
 FROM whale.task t
 JOIN whale.ref_code trigger ON trigger.ref_code_id=t.trigger_mode_ref_id
 JOIN whale.cfg_protocol_operation_role r
   ON r.protocol_operation_def_id=t.protocol_operation_def_id
  AND r.protocol_role_ref_id=t.protocol_role_ref_id
  AND r.allowed AND r.enabled AND r.valid_to IS NULL
 LEFT JOIN whale.task_param_def d
   ON d.cfg_protocol_operation_role_id=r.cfg_protocol_operation_role_id
  AND d.enabled AND d.valid_to IS NULL
 LEFT JOIN whale.task_param_value v
   ON v.task_id=t.task_id AND v.task_param_def_id=d.task_param_def_id
  AND v.enabled AND v.valid_to IS NULL
 GROUP BY t.task_id,trigger.code,t.timeout_ms,t.retry_count
)
SELECT t.task_id,
       t.task_identifier,
       t.name_zh AS task_name_zh,
       t.name_en AS task_name_en,
       protocol.code AS protocol,
       op.operation_identifier,
       role.code AS task_role,
       t.record_revision AS version,
       a.ast_asset_id AS asset_id,
       a.asset_identifier,
       a.name_zh AS asset_name,
       at.name_zh AS asset_type_name,
       c.cfg_connection_id AS conn_id,
       c.connection_identifier,
       t.task_point_table_id,
       COALESCE(param_agg.task_params_json,'{}'::jsonb) AS task_params_json,
       status.code AS task_status,
       t.valid_from::date AS start_date,
       t.valid_to::date AS end_date
FROM whale.task t
JOIN whale.cfg_connection c ON c.cfg_connection_id=t.cfg_connection_id
JOIN whale.ast_asset a ON a.ast_asset_id=c.asset_id
JOIN whale.ref_code at ON at.ref_code_id=a.asset_type_ref_id
JOIN whale.cfg_protocol_operation_def op ON op.cfg_protocol_operation_def_id=t.protocol_operation_def_id
JOIN whale.ref_code protocol ON protocol.ref_code_id=op.protocol_ref_id
JOIN whale.ref_code role ON role.ref_code_id=t.protocol_role_ref_id
JOIN whale.ref_code status ON status.ref_code_id=t.task_status_ref_id
LEFT JOIN param_agg ON param_agg.task_id=t.task_id
WHERE t.valid_to IS NULL
ORDER BY protocol.sort_order,a.asset_identifier,op.operation_identifier,t.task_identifier;
COMMENT ON VIEW whale.vw_task_full IS '【配置数据】当前任务摘要视图。仅返回每个 task_identifier 的当前版本，不展开点位明细；点位通过 task_point_table_id 查询 vw_task_point_item。';
COMMENT ON COLUMN whale.vw_task_full.task_id IS '当前任务版本主键。';
COMMENT ON COLUMN whale.vw_task_full.task_identifier IS '跨版本稳定任务标识。';
COMMENT ON COLUMN whale.vw_task_full.task_name_zh IS '任务中文名。';
COMMENT ON COLUMN whale.vw_task_full.task_name_en IS '任务英文名。';
COMMENT ON COLUMN whale.vw_task_full.protocol IS '协议 code。';
COMMENT ON COLUMN whale.vw_task_full.operation_identifier IS '协议原生操作稳定标识。';
COMMENT ON COLUMN whale.vw_task_full.task_role IS '按协议规范命名的任务角色。';
COMMENT ON COLUMN whale.vw_task_full.version IS '任务 record_revision。';
COMMENT ON COLUMN whale.vw_task_full.asset_id IS '连接归属资产主键。';
COMMENT ON COLUMN whale.vw_task_full.asset_identifier IS '资产稳定标识。';
COMMENT ON COLUMN whale.vw_task_full.asset_name IS '资产中文名。';
COMMENT ON COLUMN whale.vw_task_full.asset_type_name IS '资产类型中文名。';
COMMENT ON COLUMN whale.vw_task_full.conn_id IS '任务使用的 cfg_connection_id。';
COMMENT ON COLUMN whale.vw_task_full.connection_identifier IS '连接稳定标识。';
COMMENT ON COLUMN whale.vw_task_full.task_point_table_id IS '任务使用或复用的任务点表主键。';
COMMENT ON COLUMN whale.vw_task_full.task_params_json IS '任务固定参数与 task_param_value 聚合结果。';
COMMENT ON COLUMN whale.vw_task_full.task_status IS '任务当前状态；FAILED 表示失败退出。';
COMMENT ON COLUMN whale.vw_task_full.start_date IS '当前任务版本生效日期。';
COMMENT ON COLUMN whale.vw_task_full.end_date IS '当前任务版本失效日期。';

CREATE OR REPLACE VIEW whale.vw_task_point_item AS
SELECT i.task_point_table_id,
       pt.point_table_identifier,
       i.task_point_item_id,
       protocol.code AS protocol,
       i.protocol_point_table_id,
       i.protocol_point_item_id,
       role.code AS point_role,
       i.scan_order,
       sample.code AS sample_mode
FROM whale.task_point_item i
JOIN whale.task_point_table pt ON pt.task_point_table_id=i.task_point_table_id
JOIN whale.ref_code protocol ON protocol.ref_code_id=i.protocol_ref_id
JOIN whale.ref_code role ON role.ref_code_id=i.point_role_ref_id
JOIN whale.ref_code sample ON sample.ref_code_id=i.sample_mode_ref_id
WHERE i.enabled AND i.valid_to IS NULL
  AND pt.enabled AND pt.valid_to IS NULL
ORDER BY i.task_point_table_id,i.scan_order,i.task_point_item_id;
COMMENT ON VIEW whale.vw_task_point_item IS '【配置数据】任务点表成员视图。保留 task_point_table_id 层级，使多个任务能够复用同一任务点表。';
COMMENT ON COLUMN whale.vw_task_point_item.task_point_table_id IS '可由 vw_task_full.task_point_table_id 关联的任务点表主键。';
COMMENT ON COLUMN whale.vw_task_point_item.point_table_identifier IS '任务点表稳定标识。';
COMMENT ON COLUMN whale.vw_task_point_item.task_point_item_id IS '任务点表成员主键。';
COMMENT ON COLUMN whale.vw_task_point_item.protocol IS '点位所属协议。';
COMMENT ON COLUMN whale.vw_task_point_item.protocol_point_table_id IS '协议物理点表主键。';
COMMENT ON COLUMN whale.vw_task_point_item.protocol_point_item_id IS '协议物理点项主键。';
COMMENT ON COLUMN whale.vw_task_point_item.point_role IS '点在任务中的角色。';
COMMENT ON COLUMN whale.vw_task_point_item.scan_order IS '任务点处理顺序。';
COMMENT ON COLUMN whale.vw_task_point_item.sample_mode IS '任务点采样或触发模式。';


CREATE OR REPLACE VIEW whale.vw_modbus_point_item AS
SELECT
    item.cfg_modbus_point_item_id AS point_item_id,
    item.cfg_modbus_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    fc.code AS function_code,
    area.code AS register_area,
    item.register_address AS address,
    item.register_count AS count,
    item.bit_offset,
    dtype.code AS data_type,
    byte_order.code AS byte_order,
    word_order.code AS word_order
FROM whale.cfg_modbus_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
JOIN whale.ref_code fc ON fc.ref_code_id = item.function_code_ref_id
LEFT JOIN whale.ref_code area ON area.ref_code_id = item.register_area_ref_id
JOIN whale.ref_code dtype ON dtype.ref_code_id = item.protocol_data_type_ref_id
LEFT JOIN whale.ref_code byte_order ON byte_order.ref_code_id = item.byte_order_ref_id
LEFT JOIN whale.ref_code word_order ON word_order.ref_code_id = item.word_order_ref_id
WHERE item.enabled = TRUE AND item.valid_to IS NULL
ORDER BY item.cfg_modbus_point_table_id, item.cfg_modbus_point_item_id;
COMMENT ON VIEW whale.vw_modbus_point_item IS '【配置数据】MODBUS 点位执行视图。table_id 表示 cfg_modbus_point_table_id；point_item_id 才是点位主键。字段名称尽量贴近 pymodbus API 参数。';
COMMENT ON COLUMN whale.vw_modbus_point_item.point_item_id IS '协议点位主键，来自对应 cfg_xxx_point_item_id；外部程序通过 vw_task_point_item.protocol_point_item_id 匹配该字段。';
COMMENT ON COLUMN whale.vw_modbus_point_item.table_id IS '协议点表主键，来自对应 cfg_xxx_point_table_id；注意它不是点位主键。';
COMMENT ON COLUMN whale.vw_modbus_point_item.point_identifier IS '协议点业务稳定标识，来自对应 cfg_xxx_point_item.point_identifier。';
COMMENT ON COLUMN whale.vw_modbus_point_item.semantic_identifier IS '业务测量、状态、控制或发布语义标识，来自 cfg_measurement_semantic.measurement_identifier。';
COMMENT ON COLUMN whale.vw_modbus_point_item.semantic_name IS '业务语义中文名，来自 cfg_measurement_semantic.name_zh。';
COMMENT ON COLUMN whale.vw_modbus_point_item.unit_code IS '工程单位 code，来自 ref_code.ref_type=UNIT。';
COMMENT ON COLUMN whale.vw_modbus_point_item.scale IS '原始值转换为工程值的比例系数，来自 scale_factor。';
COMMENT ON COLUMN whale.vw_modbus_point_item.offset_value IS '原始值转换为工程值的偏移量。';
COMMENT ON COLUMN whale.vw_modbus_point_item.value_min IS '工程值允许下限。';
COMMENT ON COLUMN whale.vw_modbus_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_modbus_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_modbus_point_item.function_code IS 'MODBUS 功能码 code，用于驱动 facade 分派 read_coils/read_discrete_inputs/read_holding_registers/read_input_registers/write_*。';
COMMENT ON COLUMN whale.vw_modbus_point_item.register_area IS 'MODBUS 地址区 code。';
COMMENT ON COLUMN whale.vw_modbus_point_item.address IS 'MODBUS API address 参数，来自 register_address。';
COMMENT ON COLUMN whale.vw_modbus_point_item.count IS 'MODBUS API count 参数，来自 register_count。';
COMMENT ON COLUMN whale.vw_modbus_point_item.bit_offset IS '寄存器内位偏移；不适用时为空。';
COMMENT ON COLUMN whale.vw_modbus_point_item.data_type IS '协议原始数据类型 code。';
COMMENT ON COLUMN whale.vw_modbus_point_item.byte_order IS 'MODBUS 字节序 code。';
COMMENT ON COLUMN whale.vw_modbus_point_item.word_order IS 'MODBUS 字序 code。';

CREATE OR REPLACE VIEW whale.vw_opcua_point_item AS
SELECT
    item.cfg_opcua_point_item_id AS point_item_id,
    item.cfg_opcua_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    item.namespace_index,
    item.namespace_uri,
    item.node_id,
    item.browse_path,
    item.attribute_id,
    dtype.code AS data_type,
    dtype.code AS variant_type,
    item.value_rank,
    item.array_length
FROM whale.cfg_opcua_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
JOIN whale.ref_code dtype ON dtype.ref_code_id = item.protocol_data_type_ref_id
