COMMENT ON COLUMN whale.vw_opcua_point_item.unit_code IS '工程单位 code，来自 ref_code.ref_type=UNIT。';
COMMENT ON COLUMN whale.vw_opcua_point_item.scale IS '原始值转换为工程值的比例系数，来自 scale_factor。';
COMMENT ON COLUMN whale.vw_opcua_point_item.offset_value IS '原始值转换为工程值的偏移量。';
COMMENT ON COLUMN whale.vw_opcua_point_item.value_min IS '工程值允许下限。';
COMMENT ON COLUMN whale.vw_opcua_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_opcua_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_opcua_point_item.namespace_index IS 'OPC UA namespace index。';
COMMENT ON COLUMN whale.vw_opcua_point_item.namespace_uri IS 'OPC UA namespace URI。';
COMMENT ON COLUMN whale.vw_opcua_point_item.node_id IS 'OPC UA NodeId。';
COMMENT ON COLUMN whale.vw_opcua_point_item.browse_path IS 'OPC UA browse path。';
COMMENT ON COLUMN whale.vw_opcua_point_item.attribute_id IS 'OPC UA attribute id。';
COMMENT ON COLUMN whale.vw_opcua_point_item.data_type IS '协议原始数据类型 code。';
COMMENT ON COLUMN whale.vw_opcua_point_item.variant_type IS 'OPC UA Variant 类型；当前由协议数据类型映射。';
COMMENT ON COLUMN whale.vw_opcua_point_item.value_rank IS 'OPC UA value rank。';
COMMENT ON COLUMN whale.vw_opcua_point_item.array_length IS '数组长度；标量可为空或 1。';

