COMMENT ON COLUMN whale.vw_ads_point_item.point_identifier IS '协议点业务稳定标识，来自对应 cfg_xxx_point_item.point_identifier。';
COMMENT ON COLUMN whale.vw_ads_point_item.semantic_identifier IS '业务测量、状态、控制或发布语义标识，来自 cfg_measurement_semantic.measurement_identifier。';
