COMMENT ON COLUMN whale.vw_ads_point_item.unit_code IS '工程单位 code，来自 ref_code.ref_type=UNIT。';
COMMENT ON COLUMN whale.vw_ads_point_item.scale IS '原始值转换为工程值的比例系数，来自 scale_factor。';
COMMENT ON COLUMN whale.vw_ads_point_item.offset_value IS '原始值转换为工程值的偏移量。';
COMMENT ON COLUMN whale.vw_ads_point_item.value_min IS '工程值允许下限。';
COMMENT ON COLUMN whale.vw_ads_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_ads_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_ads_point_item.symbol_name IS 'ADS 变量符号名，对应 pyads read_by_name/write_by_name 参数。';
