CREATE OR REPLACE VIEW whale.vw_iec101_point_item AS
SELECT
    item.cfg_iec101_point_item_id AS point_item_id,
    item.cfg_iec101_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    type_id.code AS type_id,
    item.common_address,
    item.information_object_address AS io_address,
    dtype.code AS data_type,
    item.quality_descriptor_enabled
FROM whale.cfg_iec101_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
JOIN whale.ref_code type_id ON type_id.ref_code_id = item.type_id_ref_id
JOIN whale.ref_code dtype ON dtype.ref_code_id = item.protocol_data_type_ref_id
WHERE item.enabled = TRUE AND item.valid_to IS NULL
ORDER BY item.cfg_iec101_point_table_id, item.cfg_iec101_point_item_id;
COMMENT ON VIEW whale.vw_iec101_point_item IS '【配置数据】IEC101 点位执行视图。table_id 表示 cfg_iec101_point_table_id；io_address 是 IEC101 信息对象地址。';
COMMENT ON COLUMN whale.vw_iec101_point_item.point_item_id IS '协议点位主键，来自对应 cfg_xxx_point_item_id；外部程序通过 vw_task_point_item.protocol_point_item_id 匹配该字段。';
COMMENT ON COLUMN whale.vw_iec101_point_item.table_id IS '协议点表主键，来自对应 cfg_xxx_point_table_id；注意它不是点位主键。';
COMMENT ON COLUMN whale.vw_iec101_point_item.point_identifier IS '协议点业务稳定标识，来自对应 cfg_xxx_point_item.point_identifier。';
COMMENT ON COLUMN whale.vw_iec101_point_item.semantic_identifier IS '业务测量、状态、控制或发布语义标识，来自 cfg_measurement_semantic.measurement_identifier。';
COMMENT ON COLUMN whale.vw_iec101_point_item.semantic_name IS '业务语义中文名，来自 cfg_measurement_semantic.name_zh。';
COMMENT ON COLUMN whale.vw_iec101_point_item.unit_code IS '工程单位 code，来自 ref_code.ref_type=UNIT。';
COMMENT ON COLUMN whale.vw_iec101_point_item.scale IS '原始值转换为工程值的比例系数，来自 scale_factor。';
COMMENT ON COLUMN whale.vw_iec101_point_item.offset_value IS '原始值转换为工程值的偏移量。';
COMMENT ON COLUMN whale.vw_iec101_point_item.value_min IS '工程值允许下限。';
COMMENT ON COLUMN whale.vw_iec101_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_iec101_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_iec101_point_item.type_id IS 'IEC101/IEC104 ASDU Type ID code。';
COMMENT ON COLUMN whale.vw_iec101_point_item.common_address IS 'IEC101/IEC104 common address。';
COMMENT ON COLUMN whale.vw_iec101_point_item.io_address IS 'IEC101/IEC104 information object address。';
COMMENT ON COLUMN whale.vw_iec101_point_item.data_type IS '协议原始数据类型 code。';
COMMENT ON COLUMN whale.vw_iec101_point_item.quality_descriptor_enabled IS '是否解析或生成质量描述位。';



CREATE OR REPLACE VIEW whale.vw_iec104_point_item AS
SELECT item.cfg_iec104_point_item_id AS point_item_id,
       item.cfg_iec104_point_table_id AS table_id,
       item.point_identifier, item.name_zh AS point_name_zh, item.name_en AS point_name_en,
       sem.measurement_identifier AS semantic_identifier, sem.name_zh AS semantic_name_zh, sem.name_en AS semantic_name_en,
       unit.code AS unit_code, unit.name_zh AS unit_name_zh,
       item.scale_factor AS scale, item.offset_value, item.value_min, item.value_max, item.allowed_values,
       type_id.code AS type_id, type_def.type_id_value,
       type_id.name_zh AS type_id_name_zh, type_id.name_en AS type_id_name_en,
       category.code AS type_category,
       value_type.code AS information_value_type,
       time_tag.code AS time_tag_type,
       type_def.point_registration_supported,
       type_def.general_interrogation_supported,
       type_def.counter_interrogation_supported,
       type_def.periodic_transmission_supported,
       type_def.spontaneous_transmission_supported,
       type_def.command_mode_supported,
       type_def.related_io_supported,
       item.common_address, item.information_object_address AS io_address,
       command_mode.code AS command_mode,
       item.report_ms, item.spontaneous_deadband, item.spontaneous_min_interval_ms,
       item.related_io_address, item.related_io_autoreturn,
       dtype.code AS data_type, item.quality_descriptor_enabled
FROM whale.cfg_iec104_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id=item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id=item.engineering_unit_ref_id
JOIN whale.cfg_iec104_type_def type_def ON type_def.type_id_ref_id=item.type_id_ref_id AND type_def.enabled=TRUE
JOIN whale.ref_code type_id ON type_id.ref_code_id=type_def.type_id_ref_id
JOIN whale.ref_code category ON category.ref_code_id=type_def.type_category_ref_id
JOIN whale.ref_code value_type ON value_type.ref_code_id=type_def.information_value_type_ref_id
JOIN whale.ref_code time_tag ON time_tag.ref_code_id=type_def.time_tag_type_ref_id
LEFT JOIN whale.ref_code command_mode ON command_mode.ref_code_id=item.command_mode_ref_id
JOIN whale.ref_code dtype ON dtype.ref_code_id=item.protocol_data_type_ref_id
WHERE item.enabled AND item.valid_to IS NULL
ORDER BY item.cfg_iec104_point_table_id,item.common_address,item.information_object_address;
COMMENT ON VIEW whale.vw_iec104_point_item IS '【配置数据】统一 IEC104 点位执行视图。完整输出 c104.Point 注册参数、适配器自发上送参数及 cfg_iec104_type_def 中的 Type ID 能力。';
COMMENT ON COLUMN whale.vw_iec104_point_item.point_item_id IS 'IEC104 点位主键。';
COMMENT ON COLUMN whale.vw_iec104_point_item.table_id IS 'IEC104 点表主键。';
COMMENT ON COLUMN whale.vw_iec104_point_item.point_identifier IS '点位业务标识。';
COMMENT ON COLUMN whale.vw_iec104_point_item.point_name_zh IS '点位中文名。';
COMMENT ON COLUMN whale.vw_iec104_point_item.point_name_en IS '点位英文名。';
COMMENT ON COLUMN whale.vw_iec104_point_item.semantic_identifier IS '业务语义标识。';
COMMENT ON COLUMN whale.vw_iec104_point_item.semantic_name_zh IS '业务语义中文名。';
COMMENT ON COLUMN whale.vw_iec104_point_item.semantic_name_en IS '业务语义英文名。';
COMMENT ON COLUMN whale.vw_iec104_point_item.unit_code IS '工程单位 code。';
COMMENT ON COLUMN whale.vw_iec104_point_item.unit_name_zh IS '工程单位中文名。';
COMMENT ON COLUMN whale.vw_iec104_point_item.scale IS '原始值转工程值比例。';
COMMENT ON COLUMN whale.vw_iec104_point_item.offset_value IS '原始值转工程值偏移。';
COMMENT ON COLUMN whale.vw_iec104_point_item.value_min IS '工程值下限。';
