CREATE OR REPLACE VIEW whale.vw_iec61850_mms_point_item AS
SELECT
    item.cfg_iec61850_mms_point_item_id AS point_item_id,
    item.cfg_iec61850_mms_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    item.logical_device,
    item.logical_node,
    item.data_object,
    item.data_attribute,
    item.object_reference,
    fc.code AS functional_constraint,
    cdc.code AS cdc,
    dtype.code AS btype,
    item.data_attribute_path
FROM whale.cfg_iec61850_mms_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
JOIN whale.ref_code fc ON fc.ref_code_id = item.fc_ref_id
JOIN whale.ref_code cdc ON cdc.ref_code_id = item.cdc_ref_id
JOIN whale.ref_code dtype ON dtype.ref_code_id = item.protocol_data_type_ref_id
WHERE item.enabled = TRUE AND item.valid_to IS NULL
ORDER BY item.cfg_iec61850_mms_point_table_id, item.cfg_iec61850_mms_point_item_id;
COMMENT ON VIEW whale.vw_iec61850_mms_point_item IS '【配置数据】IEC61850 MMS 点位执行视图。table_id 表示 cfg_iec61850_mms_point_table_id；字段名称遵循 IEC61850 语义。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.point_item_id IS '协议点位主键，来自对应 cfg_xxx_point_item_id；外部程序通过 vw_task_point_item.protocol_point_item_id 匹配该字段。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.table_id IS '协议点表主键，来自对应 cfg_xxx_point_table_id；注意它不是点位主键。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.point_identifier IS '协议点业务稳定标识，来自对应 cfg_xxx_point_item.point_identifier。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.semantic_identifier IS '业务测量、状态、控制或发布语义标识，来自 cfg_measurement_semantic.measurement_identifier。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.semantic_name IS '业务语义中文名，来自 cfg_measurement_semantic.name_zh。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.unit_code IS '工程单位 code，来自 ref_code.ref_type=UNIT。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.scale IS '原始值转换为工程值的比例系数，来自 scale_factor。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.offset_value IS '原始值转换为工程值的偏移量。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.value_min IS '工程值允许下限。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.logical_device IS 'IEC61850 logical device。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.logical_node IS 'IEC61850 logical node。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.data_object IS 'IEC61850 data object。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.data_attribute IS 'IEC61850 data attribute。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.object_reference IS 'IEC61850 对象引用，供 libiec61850 read/write/operate 使用。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.functional_constraint IS 'IEC61850 functional constraint code。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.cdc IS 'IEC61850 common data class code。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.btype IS 'IEC61850 basic type / 协议基础类型 code。';
COMMENT ON COLUMN whale.vw_iec61850_mms_point_item.data_attribute_path IS 'IEC61850 数据属性路径。';

CREATE OR REPLACE VIEW whale.vw_iec61850_goose_point_item AS
SELECT
    item.cfg_iec61850_goose_point_item_id AS point_item_id,
    item.cfg_iec61850_goose_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    item.goose_control_ref AS go_cb_ref,
    item.dataset_ref,
    item.member_index,
    item.object_reference,
    cdc.code AS cdc,
    btype.code AS btype
FROM whale.cfg_iec61850_goose_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
LEFT JOIN whale.ref_code cdc ON cdc.ref_code_id = item.cdc_ref_id
LEFT JOIN whale.ref_code btype ON btype.ref_code_id = item.btype_ref_id
WHERE item.enabled = TRUE AND item.valid_to IS NULL
ORDER BY item.cfg_iec61850_goose_point_table_id, item.cfg_iec61850_goose_point_item_id;
