COMMENT ON COLUMN whale.vw_iec61850_goose_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_iec61850_goose_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_iec61850_goose_point_item.go_cb_ref IS 'IEC61850 GOOSE control block reference。';
COMMENT ON COLUMN whale.vw_iec61850_goose_point_item.dataset_ref IS 'IEC61850 dataset reference。';
COMMENT ON COLUMN whale.vw_iec61850_goose_point_item.member_index IS 'IEC61850 dataset 成员序号。';
COMMENT ON COLUMN whale.vw_iec61850_goose_point_item.object_reference IS 'IEC61850 对象引用，供 libiec61850 read/write/operate 使用。';
