CREATE OR REPLACE VIEW whale.vw_iec61850_sv_point_item AS
SELECT
    item.cfg_iec61850_sv_point_item_id AS point_item_id,
    item.cfg_iec61850_sv_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    item.sv_control_ref AS sv_id,
    item.dataset_ref,
    item.sample_channel,
    item.sample_index,
    phase.code AS phase,
    quantity.code AS quantity,
    cdc.code AS cdc,
    btype.code AS btype
FROM whale.cfg_iec61850_sv_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
LEFT JOIN whale.ref_code phase ON phase.ref_code_id = item.phase_ref_id
LEFT JOIN whale.ref_code quantity ON quantity.ref_code_id = item.quantity_ref_id
LEFT JOIN whale.ref_code cdc ON cdc.ref_code_id = item.cdc_ref_id
LEFT JOIN whale.ref_code btype ON btype.ref_code_id = item.btype_ref_id
WHERE item.enabled = TRUE AND item.valid_to IS NULL
ORDER BY item.cfg_iec61850_sv_point_table_id, item.cfg_iec61850_sv_point_item_id;
