CREATE OR REPLACE VIEW whale.vw_http_rest_point_item AS
SELECT
    item.cfg_http_rest_point_item_id AS point_item_id,
    item.cfg_http_rest_point_table_id AS table_id,
    item.point_identifier,
    sem.measurement_identifier AS semantic_identifier,
    sem.name_zh AS semantic_name,
    unit.code AS unit_code,
    item.scale_factor AS scale,
    item.offset_value,
    item.value_min,
    item.value_max,
    item.allowed_values,
    method.code AS http_method,
    item.resource_path,
    item.query_param_path AS params_path,
    item.request_body_path AS json_body_path,
    item.response_body_path AS response_json_path,
    fmt.code AS payload_encoding,
    dtype.code AS data_type
FROM whale.cfg_http_rest_point_item item
JOIN whale.cfg_measurement_semantic sem ON sem.cfg_measurement_semantic_id = item.measurement_semantic_id
JOIN whale.ref_code unit ON unit.ref_code_id = item.engineering_unit_ref_id
JOIN whale.ref_code method ON method.ref_code_id = item.http_method_ref_id
JOIN whale.ref_code fmt ON fmt.ref_code_id = item.payload_format_ref_id
JOIN whale.ref_code dtype ON dtype.ref_code_id = item.protocol_data_type_ref_id
WHERE item.enabled = TRUE AND item.valid_to IS NULL
ORDER BY item.cfg_http_rest_point_table_id, item.cfg_http_rest_point_item_id;
COMMENT ON VIEW whale.vw_http_rest_point_item IS '【配置数据】HTTP REST 点位执行视图。table_id 表示 cfg_http_rest_point_table_id；params_path/json_body_path/response_json_path 分别对应请求查询参数、请求 JSON 体和响应 JSON 解析路径。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.point_item_id IS '协议点位主键，来自对应 cfg_xxx_point_item_id；外部程序通过 vw_task_point_item.protocol_point_item_id 匹配该字段。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.table_id IS '协议点表主键，来自对应 cfg_xxx_point_table_id；注意它不是点位主键。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.point_identifier IS '协议点业务稳定标识，来自对应 cfg_xxx_point_item.point_identifier。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.semantic_identifier IS '业务测量、状态、控制或发布语义标识，来自 cfg_measurement_semantic.measurement_identifier。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.semantic_name IS '业务语义中文名，来自 cfg_measurement_semantic.name_zh。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.unit_code IS '工程单位 code，来自 ref_code.ref_type=UNIT。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.scale IS '原始值转换为工程值的比例系数，来自 scale_factor。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.offset_value IS '原始值转换为工程值的偏移量。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.value_min IS '工程值允许下限。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.value_max IS '工程值允许上限。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.allowed_values IS '离散工程值允许集合，逗号分隔。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.http_method IS 'HTTP 方法 code。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.resource_path IS 'HTTP REST 资源路径。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.params_path IS 'HTTP 请求查询参数路径，对应 httpx/requests params。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.json_body_path IS 'HTTP 请求 JSON body 字段路径，对应 httpx/requests json。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.response_json_path IS 'HTTP 响应 JSON 字段解析路径。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.payload_encoding IS '载荷编码格式 code。';
COMMENT ON COLUMN whale.vw_http_rest_point_item.data_type IS '协议原始数据类型 code。';

-- common point view column comments


CREATE OR REPLACE VIEW whale.vw_topo_comm_full AS
SELECT
    c.topo_comm_connection_id,
    fn.name_zh AS from_node_name,
    fi.name_zh AS from_interface_name,
    e.name_zh AS edge_name,
    ti.name_zh AS to_interface_name,
    tn.name_zh AS to_node_name,
    fn.asset_id AS from_node_asset_id,
    tn.asset_id AS to_node_asset_id
FROM whale.topo_comm_connection c
JOIN whale.topo_comm_element fn ON fn.topo_comm_element_id = c.from_node_id
JOIN whale.topo_comm_element fi ON fi.topo_comm_element_id = c.from_interface_id
JOIN whale.topo_comm_element e ON e.topo_comm_element_id = c.edge_id
JOIN whale.topo_comm_element ti ON ti.topo_comm_element_id = c.to_interface_id
JOIN whale.topo_comm_element tn ON tn.topo_comm_element_id = c.to_node_id
WHERE c.enabled = TRUE AND c.valid_to IS NULL
ORDER BY c.topo_comm_connection_id;
COMMENT ON VIEW whale.vw_topo_comm_full IS '【配置数据】通信拓扑执行视图。按 node-interface-edge-interface-node 展示，字段名与注释保持一致。';
COMMENT ON COLUMN whale.vw_topo_comm_full.topo_comm_connection_id IS '通信拓扑连接主键。';
COMMENT ON COLUMN whale.vw_topo_comm_full.from_node_name IS '起点通信节点名称。';
COMMENT ON COLUMN whale.vw_topo_comm_full.from_interface_name IS '起点通信接口名称。';
COMMENT ON COLUMN whale.vw_topo_comm_full.edge_name IS '通信链路名称。';
COMMENT ON COLUMN whale.vw_topo_comm_full.to_interface_name IS '终点通信接口名称。';
COMMENT ON COLUMN whale.vw_topo_comm_full.to_node_name IS '终点通信节点名称。';
COMMENT ON COLUMN whale.vw_topo_comm_full.from_node_asset_id IS '起点节点关联资产主键；纯拓扑节点可为空。';
COMMENT ON COLUMN whale.vw_topo_comm_full.to_node_asset_id IS '终点节点关联资产主键；纯拓扑节点可为空。';

CREATE OR REPLACE VIEW whale.vw_topo_elec_full AS
SELECT
    c.topo_elec_connection_id,
    fn.name_zh AS from_node_name,
    fi.name_zh AS from_interface_name,
    e.name_zh AS edge_name,
    ti.name_zh AS to_interface_name,
    tn.name_zh AS to_node_name,
    fn.asset_id AS from_node_asset_id,
    tn.asset_id AS to_node_asset_id
FROM whale.topo_elec_connection c
JOIN whale.topo_elec_element fn ON fn.topo_elec_element_id = c.from_node_id
JOIN whale.topo_elec_element fi ON fi.topo_elec_element_id = c.from_interface_id
JOIN whale.topo_elec_element e ON e.topo_elec_element_id = c.edge_id
JOIN whale.topo_elec_element ti ON ti.topo_elec_element_id = c.to_interface_id
JOIN whale.topo_elec_element tn ON tn.topo_elec_element_id = c.to_node_id
WHERE c.enabled = TRUE AND c.valid_to IS NULL
ORDER BY c.topo_elec_connection_id;
COMMENT ON VIEW whale.vw_topo_elec_full IS '【配置数据】电气拓扑执行视图。按 node-interface-edge-interface-node 展示，字段名与注释保持一致。';
COMMENT ON COLUMN whale.vw_topo_elec_full.topo_elec_connection_id IS '电气拓扑连接主键。';
COMMENT ON COLUMN whale.vw_topo_elec_full.from_node_name IS '起点电气节点名称。';
COMMENT ON COLUMN whale.vw_topo_elec_full.from_interface_name IS '起点电气接口名称。';
COMMENT ON COLUMN whale.vw_topo_elec_full.edge_name IS '电气连接边名称。';
COMMENT ON COLUMN whale.vw_topo_elec_full.to_interface_name IS '终点电气接口名称。';
COMMENT ON COLUMN whale.vw_topo_elec_full.to_node_name IS '终点电气节点名称。';
COMMENT ON COLUMN whale.vw_topo_elec_full.from_node_asset_id IS '起点节点关联资产主键；母线/PCC/外部电网等纯拓扑节点可为空。';
COMMENT ON COLUMN whale.vw_topo_elec_full.to_node_asset_id IS '终点节点关联资产主键；母线/PCC/外部电网等纯拓扑节点可为空。';


-- -----------------------------------------------------------------------------
-- View column comment coverage check
-- This block guarantees that every view column in whale.vw_% has a
-- non-empty COMMENT ON COLUMN persisted in pg_description.
-- -----------------------------------------------------------------------------
DO $$
DECLARE
    missing_count INTEGER;
    missing_detail TEXT;
BEGIN
    SELECT COUNT(*),
           string_agg(format('%I.%I', c.relname, a.attname), ', ' ORDER BY c.relname, a.attnum)
      INTO missing_count, missing_detail
    FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_namespace n
      ON n.oid = c.relnamespace
    JOIN pg_catalog.pg_attribute a
      ON a.attrelid = c.oid
     AND a.attnum > 0
     AND NOT a.attisdropped
    LEFT JOIN pg_catalog.pg_description d
      ON d.objoid = c.oid
     AND d.objsubid = a.attnum
    WHERE n.nspname = 'whale'
      AND c.relkind IN ('v', 'm')
      AND c.relname LIKE 'vw\_%' ESCAPE '\'
      AND NULLIF(btrim(d.description), '') IS NULL;

    IF missing_count > 0 THEN
        RAISE EXCEPTION 'Missing COMMENT ON COLUMN for % view columns: %', missing_count, missing_detail;
    END IF;
END $$;


-- -----------------------------------------------------------------------------
-- Stable identifier lookup functions
-- These schema objects belong to DDL rather than basic/sample data files.
-- -----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION whale.ref_code_id(p_type TEXT, p_code TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT ref_code_id INTO v_id FROM whale.ref_code WHERE ref_type=p_type AND code=p_code AND enabled=true ORDER BY ref_code_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing ref_code %.%', p_type, p_code; END IF;
    RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION whale.asset_id(p_identifier TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT ast_asset_id INTO v_id FROM whale.ast_asset WHERE asset_identifier=p_identifier AND enabled=true ORDER BY ast_asset_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing asset %', p_identifier; END IF;
    RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION whale.model_id(p_identifier TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT ast_asset_model_id INTO v_id FROM whale.ast_asset_model WHERE model_identifier=p_identifier AND enabled=true ORDER BY ast_asset_model_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing model %', p_identifier; END IF;
    RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION whale.connection_id(p_identifier TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT cfg_connection_id INTO v_id FROM whale.cfg_connection WHERE connection_identifier=p_identifier AND enabled=true ORDER BY cfg_connection_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing connection %', p_identifier; END IF;
    RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION whale.semantic_id(p_identifier TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT cfg_measurement_semantic_id INTO v_id FROM whale.cfg_measurement_semantic WHERE measurement_identifier=p_identifier AND enabled=true ORDER BY cfg_measurement_semantic_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing semantic %', p_identifier; END IF;
    RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION whale.topo_elec_element_id(p_identifier TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT topo_elec_element_id INTO v_id FROM whale.topo_elec_element WHERE element_identifier=p_identifier AND enabled=true ORDER BY topo_elec_element_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing elec topology element %', p_identifier; END IF;
    RETURN v_id;
END; $$;

CREATE OR REPLACE FUNCTION whale.topo_comm_element_id(p_identifier TEXT)
RETURNS BIGINT LANGUAGE plpgsql AS $$
DECLARE v_id BIGINT;
BEGIN
    SELECT topo_comm_element_id INTO v_id FROM whale.topo_comm_element WHERE element_identifier=p_identifier AND enabled=true ORDER BY topo_comm_element_id DESC LIMIT 1;
    IF v_id IS NULL THEN RAISE EXCEPTION 'Missing comm topology element %', p_identifier; END IF;
    RETURN v_id;
END; $$;


CREATE OR REPLACE FUNCTION whale.protocol_data_type_id(p_data_type_ref_id BIGINT)
RETURNS BIGINT AS $$
DECLARE
    v_code TEXT;
    v_id BIGINT;
BEGIN
    SELECT code INTO v_code FROM whale.ref_code WHERE ref_code_id = p_data_type_ref_id;
    SELECT ref_code_id INTO v_id FROM whale.ref_code WHERE ref_type='PROTOCOL_DATA_TYPE' AND code=v_code AND enabled=true ORDER BY ref_code_id DESC LIMIT 1;
    IF v_id IS NULL THEN
        SELECT ref_code_id INTO v_id FROM whale.ref_code WHERE ref_type='PROTOCOL_DATA_TYPE' AND code='FLOAT32' AND enabled=true ORDER BY ref_code_id DESC LIMIT 1;
    END IF;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

COMMIT;
